/* locations.js — the whole point of the game.
 *
 *   n   name shown as the target ("find this")
 *   c   country, as Natural Earth spells it (test/headless.js checks every one
 *       against the actual polygon, so a typo or a flipped sign gets caught)
 *   lat/lon  decimal degrees
 *   d   difficulty 1 (everyone knows it) .. 5 (you either know it or you don't)
 *   r   region bucket, used for the stats breakdown
 *   q   the hook you read before guessing — a real event, no spoilers about where
 *   s   the story you get after guessing
 *
 * Difficulty is about how well you can PLACE it, not whether you've heard of it.
 * Reykjavik is famous and easy; Bratislava is famous and lands people in Croatia.
 */
var LOCATIONS = [

  /* ---------------------------------------------------------------- Europe */
  { n: 'Paris', c: 'France', lat: 48.8566, lon: 2.3522, d: 1, r: 'Europe',
    q: 'On 14 July 1789 a crowd took a fortress prison holding seven inmates.',
    s: 'The Bastille was nearly empty and slated for demolition anyway, but pulling it down became the image of the Revolution. France still marks the date as its national day.' },
  { n: 'London', c: 'United Kingdom', lat: 51.5072, lon: -0.1276, d: 1, r: 'Europe',
    q: 'A bakery fire on Pudding Lane in 1666 burned for four days and took 13,200 houses.',
    s: 'The Great Fire destroyed most of the medieval walled city but killed remarkably few people. Christopher Wren rebuilt 51 churches in the ashes, St Paul’s among them.' },
  { n: 'Rome', c: 'Italy', lat: 41.9028, lon: 12.4964, d: 1, r: 'Europe',
    q: 'A dictator was stabbed 23 times at a meeting of the Senate in 44 BC.',
    s: 'Caesar died at the Theatre of Pompey, not the Forum — the Senate house was under repair. The site is now a sunken square full of stray cats.' },
  { n: 'Berlin', c: 'Germany', lat: 52.5200, lon: 13.4050, d: 1, r: 'Europe',
    q: 'A misread press conference on 9 November 1989 sent crowds to the checkpoints.',
    s: 'Party official Günter Schabowski was handed new travel rules minutes before going on air and said they applied "immediately". Guards, with no orders, opened the gates.' },
  { n: 'Madrid', c: 'Spain', lat: 40.4168, lon: -3.7038, d: 1, r: 'Europe',
    q: 'Philip II moved his court to this town in 1561 and made a capital out of nothing much.',
    s: 'It had no river worth the name and no cathedral, but it sat almost exactly at the centre of Iberia — a deliberate choice to be nobody’s regional capital.' },
  { n: 'Amsterdam', c: 'Netherlands', lat: 52.3676, lon: 4.9041, d: 1, r: 'Europe',
    q: 'The world’s first company with tradable shares was chartered here in 1602.',
    s: 'The Dutch East India Company invented the stock exchange as a side effect. Its shares were traded on a bridge over the Warmoesstraat before anyone built a floor for it.' },
  { n: 'Athens', c: 'Greece', lat: 37.9838, lon: 23.7275, d: 1, r: 'Europe',
    q: 'A jury of 501 citizens voted narrowly to execute a philosopher in 399 BC.',
    s: 'Socrates was convicted of impiety and corrupting the young, then drank hemlock rather than accept exile. The prison foundations are still visible on the Hill of the Muses.' },
  { n: 'Vienna', c: 'Austria', lat: 48.2082, lon: 16.3738, d: 1, r: 'Europe',
    q: 'In September 1683 a Polish cavalry charge broke a two-month Ottoman siege here.',
    s: 'Jan III Sobieski led what may be the largest cavalry charge in history down the Kahlenberg. It marked the high-water mark of Ottoman expansion into Europe.' },
  { n: 'Moscow', c: 'Russia', lat: 55.7558, lon: 37.6173, d: 1, r: 'Europe',
    q: 'Napoleon took the city in 1812 and found it burning around him.',
    s: 'Governor Rostopchin had the fire pumps removed before withdrawing. Napoleon held a ruined, foodless city for five weeks, then began the retreat that destroyed his army.' },
  { n: 'Lisbon', c: 'Portugal', lat: 38.7223, lon: -9.1393, d: 1, r: 'Europe',
    q: 'An earthquake, a fire and a tsunami hit this city on All Saints’ Day 1755.',
    s: 'The disaster killed tens of thousands in a devout, church-filled city on a holy day, and shook European philosophy — Voltaire wrote Candide partly in response.' },
  { n: 'Dublin', c: 'Ireland', lat: 53.3498, lon: -6.2603, d: 1, r: 'Europe',
    q: 'Rebels seized the General Post Office at Easter 1916 and read out a proclamation.',
    s: 'The Rising failed in six days and was unpopular at first. Executing sixteen leaders over the following weeks turned public opinion and led to independence within six years.' },
  { n: 'Stockholm', c: 'Sweden', lat: 59.3293, lon: 18.0686, d: 1, r: 'Europe',
    q: 'A brand-new warship sank 1,300 metres into its maiden voyage in 1628.',
    s: 'The Vasa was too tall and too narrow, and a gust laid her over. Cold brackish water kept the shipworms out, so she was raised in 1961 almost intact.' },
  { n: 'Venice', c: 'Italy', lat: 45.4408, lon: 12.3155, d: 1, r: 'Europe',
    q: 'In 1347 ships arriving here were held offshore for forty days.',
    s: 'That forty — quaranta — gave us the word quarantine. The republic’s plague controls were the first systematic public-health regime in Europe.' },
  { n: 'Barcelona', c: 'Spain', lat: 41.3874, lon: 2.1686, d: 1, r: 'Europe',
    q: 'A basilica begun in 1882 is still unfinished, and its architect was hit by a tram.',
    s: 'Gaudí was taken for a beggar after the accident in 1926 and left untreated for a day. He is buried in the crypt of the church he never saw finished.' },
  { n: 'Istanbul', c: 'Turkey', lat: 41.0082, lon: 28.9784, d: 1, r: 'Europe',
    q: 'Cannon broke a thousand-year-old wall here in May 1453.',
    s: 'Mehmed II’s bombard fired stone balls over 500 kg. The fall of the city is the usual bookmark for the end of the Middle Ages, and it sits on two continents.' },
  { n: 'Prague', c: 'Czechia', lat: 50.0755, lon: 14.4378, d: 1, r: 'Europe',
    q: 'Two governors were thrown out of a castle window in 1618 and survived the fall.',
    s: 'They landed in a dung heap sixteen metres below — Catholics called it divine intervention. The defenestration started the Thirty Years’ War.' },
  { n: 'Copenhagen', c: 'Denmark', lat: 55.6761, lon: 12.5683, d: 1, r: 'Europe',
    q: 'A physicist here proposed in 1913 that electrons can only occupy fixed orbits.',
    s: 'Niels Bohr’s institute became the centre of quantum physics. During the occupation he dissolved two Nobel medals in acid to hide them, and recast them after the war.' },
  { n: 'Oslo', c: 'Norway', lat: 59.9139, lon: 10.7522, d: 1, r: 'Europe',
    q: 'One of the five Nobel prizes is awarded here rather than in Stockholm.',
    s: 'Nobel’s will gave the peace prize to a committee chosen by the Norwegian parliament — nobody is quite sure why, since Norway and Sweden were in union at the time.' },
  { n: 'Warsaw', c: 'Poland', lat: 52.2297, lon: 21.0122, d: 1, r: 'Europe',
    q: 'This city rose in August 1944, held for 63 days, and was demolished street by street.',
    s: 'Around 85% of the city was destroyed. The old town was rebuilt from Bellotto’s 18th-century cityscapes — a reconstruction so thorough that UNESCO listed the copy.' },
  { n: 'Budapest', c: 'Hungary', lat: 47.4979, lon: 19.0402, d: 1, r: 'Europe',
    q: 'Two cities on opposite banks merged into one in 1873.',
    s: 'Hilly Buda and flat Pest were joined by the Chain Bridge, whose lions were carved without tongues — a detail the sculptor was mocked for until his death.' },
  { n: 'Brussels', c: 'Belgium', lat: 50.8503, lon: 4.3517, d: 1, r: 'Europe',
    q: 'A 1958 world’s fair left behind a 102-metre model of an iron crystal.',
    s: 'The Atomium magnifies a unit cell 165 billion times. It was meant to last six months and is still the city’s emblem.' },
  { n: 'Munich', c: 'Germany', lat: 48.1351, lon: 11.5820, d: 1, r: 'Europe',
    q: 'A failed putsch started in a beer hall here in November 1923.',
    s: 'Hitler’s march was stopped by police after a few hundred metres. He served nine months of a five-year sentence and wrote Mein Kampf in the cell.' },
  { n: 'Naples', c: 'Italy', lat: 40.8518, lon: 14.2681, d: 1, r: 'Europe',
    q: 'A pizza made for a visiting queen in 1889 was topped in red, white and green.',
    s: 'Raffaele Esposito named the margherita for Queen Margherita of Savoy. The city lives beside the volcano that buried Pompeii, still very much active.' },
  { n: 'Edinburgh', c: 'United Kingdom', lat: 55.9533, lon: -3.1883, d: 1, r: 'Europe',
    q: 'A castle sits on the plug of an extinct volcano above a medieval spine of a street.',
    s: 'The Royal Mile runs down a glacial crag-and-tail ridge. Body snatchers Burke and Hare sold sixteen victims to the anatomy school here in 1828.' },
  { n: 'Geneva', c: 'Switzerland', lat: 46.2044, lon: 6.1432, d: 2, r: 'Europe',
    q: 'A 27-kilometre ring buried under two countries accelerates protons here.',
    s: 'The LHC crosses the French border underground. The web was invented at the same lab in 1989 so physicists could share papers.' },
  { n: 'Sarajevo', c: 'Bosnia and Herz.', lat: 43.8563, lon: 18.4131, d: 2, r: 'Europe',
    q: 'A driver took a wrong turn on 28 June 1914 and stopped in front of a teenage gunman.',
    s: 'Gavrilo Princip had already given up after a failed bomb attempt that morning. The car reversed toward him by accident, and Europe went to war five weeks later.' },
  { n: 'Kraków', c: 'Poland', lat: 50.0647, lon: 19.9450, d: 2, r: 'Europe',
    q: 'A trumpet call from a church tower here breaks off mid-note every hour.',
    s: 'The hejnał stops where a Mongol arrow supposedly hit the trumpeter’s throat in 1241. The city was Poland’s capital for over 500 years.' },
  { n: 'Seville', c: 'Spain', lat: 37.3891, lon: -5.9845, d: 2, r: 'Europe',
    q: 'Magellan’s fleet left from this river port in 1519; one ship came back three years later.',
    s: 'Eighteen of 270 men completed the first circumnavigation. The city held a legal monopoly on trade with the Americas for two centuries.' },
  { n: 'Florence', c: 'Italy', lat: 43.7696, lon: 11.2558, d: 2, r: 'Europe',
    q: 'A dome was raised here in 1436 without any supporting scaffolding underneath.',
    s: 'Brunelleschi laid four million bricks in a herringbone pattern that held itself up as it rose. Nobody fully understood how until modern surveys.' },
  { n: 'Marseille', c: 'France', lat: 43.2965, lon: 5.3698, d: 2, r: 'Europe',
    q: 'France’s anthem is named for volunteers who marched to Paris from this port in 1792.',
    s: 'The song was written in Strasbourg, but the battalion from this city sang it all the way north, so the name stuck. Founded by Greeks around 600 BC, it is France’s oldest city.' },
  { n: 'Hamburg', c: 'Germany', lat: 53.5511, lon: 9.9937, d: 2, r: 'Europe',
    q: 'A four-piece band from Liverpool played 98 nights in a row in this port’s club district.',
    s: 'The Beatles played eight-hour sets on the Reeperbahn in 1960 and came home a different band. The city has more bridges than Venice and Amsterdam combined.' },
  { n: 'Gdańsk', c: 'Poland', lat: 54.3520, lon: 18.6466, d: 2, r: 'Europe',
    q: 'A shipyard electrician climbed a wall here in 1980 and joined a strike he then led.',
    s: 'Lech Wałęsa’s Solidarity became the first independent union in the Soviet bloc. The first shots of the Second World War were fired at the harbour mouth in 1939.' },
  { n: 'Helsinki', c: 'Finland', lat: 60.1699, lon: 24.9384, d: 2, r: 'Europe',
    q: 'A 1952 Olympics ran on a stadium tower built to be exactly 72.71 metres tall.',
    s: 'That is the length of Matti Järvinen’s 1932 gold-medal javelin throw. The city sits on a granite peninsula and its cathedral steps are a favourite for sitting still.' },
  { n: 'Reykjavík', c: 'Iceland', lat: 64.1466, lon: -21.9426, d: 2, r: 'Europe',
    q: 'Two superpowers’ leaders met here in 1986 and walked out with no deal.',
    s: 'Reagan and Gorbachev came within reach of abolishing all nuclear weapons before stalling over missile defence. Almost everything here is heated by geothermal water.' },
  { n: 'Belgrade', c: 'Serbia', lat: 44.7866, lon: 20.4489, d: 2, r: 'Europe',
    q: 'A fortress here sits where the Sava meets the Danube, and has been destroyed 44 times.',
    s: 'Kalemegdan has been Celtic, Roman, Byzantine, Serbian, Ottoman and Austrian. Few cities in Europe have been fought over more often.' },
  { n: 'Kyiv', c: 'Ukraine', lat: 50.4501, lon: 30.5234, d: 2, r: 'Europe',
    q: 'A prince had this city’s idols thrown in the river in 988 and baptised his people.',
    s: 'Volodymyr the Great’s conversion pulled the Rus into the Byzantine world. The monastery caves above the Dnipro still hold mummified monks.' },
  { n: 'Zürich', c: 'Switzerland', lat: 47.3769, lon: 8.5417, d: 2, r: 'Europe',
    q: 'An art movement was invented in a cabaret here in 1916 by people fleeing the war.',
    s: 'Dada started at the Cabaret Voltaire. Lenin was living a few streets away at the same time, waiting for a train home.' },
  { n: 'Porto', c: 'Portugal', lat: 41.1579, lon: -8.6291, d: 2, r: 'Europe',
    q: 'A fortified wine is named after this city, though it is aged across the river.',
    s: 'The lodges are in Vila Nova de Gaia. British merchants fortified the wine with brandy so it would survive the sea voyage, and accidentally invented a style.' },
  { n: 'Milan', c: 'Italy', lat: 45.4642, lon: 9.1900, d: 2, r: 'Europe',
    q: 'A mural here started flaking off the wall within twenty years of being painted.',
    s: 'Leonardo painted the Last Supper in tempera on dry plaster instead of true fresco, so it began to fail immediately. A 1943 bomb took the refectory roof but not the wall.' },
  { n: 'Bruges', c: 'Belgium', lat: 51.2093, lon: 3.2247, d: 2, r: 'Europe',
    q: 'This trading city was ruined when its channel to the sea silted up in the 1500s.',
    s: 'Being frozen out of trade froze the medieval streets in place, which is why the whole centre survives. Antwerp took the business.' },
  { n: 'Bucharest', c: 'Romania', lat: 44.4268, lon: 26.1025, d: 2, r: 'Europe',
    q: 'A dictator was booed here on 21 December 1989 and the broadcast kept rolling.',
    s: 'Ceaușescu’s face on live television as the crowd turned is one of the century’s images. He was executed four days later.' },
  { n: 'Sofia', c: 'Bulgaria', lat: 42.6977, lon: 23.3219, d: 3, r: 'Europe',
    q: 'This capital’s motto is "it grows but does not age", and a mountain sits on its doorstep.',
    s: 'Vitosha rises to 2,290 m within the city limits. A Roman church from the 4th century still stands between the presidency and a department store.' },
  { n: 'Tallinn', c: 'Estonia', lat: 59.4370, lon: 24.7536, d: 3, r: 'Europe',
    q: 'Independence was won here partly by hundreds of thousands of people singing.',
    s: 'The Singing Revolution of 1987–91 used mass song festivals as protest. A human chain of two million people linked three Baltic capitals in 1989.' },
  { n: 'Riga', c: 'Latvia', lat: 56.9496, lon: 24.1052, d: 3, r: 'Europe',
    q: 'This city claims the first decorated Christmas tree, in 1510.',
    s: 'A merchant guild put up a tree in the town square and burned it after the feast. The city also has Europe’s densest collection of art nouveau facades.' },
  { n: 'Vilnius', c: 'Lithuania', lat: 54.6872, lon: 25.2797, d: 3, r: 'Europe',
    q: 'A neighbourhood here declared itself an independent republic on April Fool’s Day 1997.',
    s: 'Užupis has a constitution including "a dog has the right to be a dog" and an army of about a dozen. The city was once called the Jerusalem of the North.' },
  { n: 'Minsk', c: 'Belarus', lat: 53.9006, lon: 27.5590, d: 3, r: 'Europe',
    q: 'This capital was rebuilt almost entirely in Stalinist style after 1944.',
    s: 'Around 80% of the buildings were gone by the end of the war, so the centre is a single continuous piece of postwar design.' },
  { n: 'Bratislava', c: 'Slovakia', lat: 48.1486, lon: 17.1077, d: 3, r: 'Europe',
    q: 'This is the only capital city bordering two other countries.',
    s: 'Austria and Hungary are both within a bike ride. It sat 60 km from Vienna behind the Iron Curtain, two capitals almost in sight of each other.' },
  { n: 'Ljubljana', c: 'Slovenia', lat: 46.0569, lon: 14.5058, d: 3, r: 'Europe',
    q: 'One architect redesigned this whole capital between the wars — bridges, market, library.',
    s: 'Jože Plečnik gave the city a single authored look. A dragon guards the main bridge, supposedly from the Argonauts’ return trip.' },
  { n: 'Zagreb', c: 'Croatia', lat: 45.8150, lon: 15.9819, d: 3, r: 'Europe',
    q: 'A museum here collects objects left over from other people’s failed relationships.',
    s: 'The Museum of Broken Relationships started as a travelling art project and became permanent. The city also claims the invention of the necktie, from Croatian mercenaries’ cravats.' },
  { n: 'Skopje', c: 'Macedonia', lat: 41.9981, lon: 21.4254, d: 3, r: 'Europe',
    q: 'An earthquake levelled this capital in 1963 and the world sent an architect.',
    s: 'Kenzo Tange won the competition to redesign it. A recent programme covered the centre in neoclassical statues, including a very large Alexander.' },
  { n: 'Tirana', c: 'Albania', lat: 41.3275, lon: 19.8187, d: 3, r: 'Europe',
    q: 'A mayor here fought urban decay by having grey apartment blocks painted in wild colours.',
    s: 'Edi Rama, a painter turned politician, later became prime minister. The country built roughly 170,000 concrete bunkers under Enver Hoxha, and most are still there.' },
  { n: 'Chișinău', c: 'Moldova', lat: 47.0105, lon: 28.8638, d: 4, r: 'Europe',
    q: 'The world’s largest wine cellar runs 200 km of tunnels under limestone near this capital.',
    s: 'Cricova and Mileștii Mici are old quarries turned into cellars with street signs underground. The country between Romania and Ukraine is among Europe’s least visited.' },
  { n: 'Podgorica', c: 'Montenegro', lat: 42.4304, lon: 19.2594, d: 4, r: 'Europe',
    q: 'This capital was called Titograd until 1992.',
    s: 'It sits where five rivers meet, was bombed over 70 times in 1944, and is one of Europe’s smallest capitals at around 150,000 people.' },
  { n: 'Bergen', c: 'Norway', lat: 60.3913, lon: 5.3221, d: 3, r: 'Europe',
    q: 'A German merchant league ran the dried-cod trade from a wooden wharf in this city.',
    s: 'Bryggen’s Hanseatic warehouses have burned and been rebuilt on the same medieval foundations for 900 years. It rains here about 240 days a year.' },
  { n: 'Volgograd', c: 'Russia', lat: 48.7080, lon: 44.5133, d: 3, r: 'Europe',
    q: 'A five-month battle for this city in 1942–43 turned the Eastern Front.',
    s: 'Then called Stalingrad, it was fought room by room; a single grain elevator changed hands repeatedly. The Motherland Calls statue was the tallest in the world when built.' },
  { n: 'Oświęcim', c: 'Poland', lat: 50.0347, lon: 19.2088, d: 4, r: 'Europe',
    q: 'A rail junction town whose German name became shorthand for the Holocaust.',
    s: 'Auschwitz was chosen for its rail links. Around 1.1 million people were murdered there; the site is preserved as a memorial and museum.' },
  { n: 'Pripyat', c: 'Ukraine', lat: 51.4045, lon: 30.0542, d: 4, r: 'Europe',
    q: 'A test of a reactor’s backup power went wrong at 1:23 a.m. on 26 April 1986.',
    s: 'The town of 49,000 was evacuated 36 hours later with residents told they would return in three days. The fairground was due to open that May Day.' },
  { n: 'Pompeii', c: 'Italy', lat: 40.7497, lon: 14.4869, d: 2, r: 'Europe',
    q: 'A town buried under four metres of ash in AD 79 and forgotten for 1,500 years.',
    s: 'Voids left by decayed bodies were filled with plaster in the 1860s, producing the casts. A nearby town was buried deeper by hot mud and is better preserved still.' },
  { n: 'Delphi', c: 'Greece', lat: 38.4824, lon: 22.5010, d: 3, r: 'Europe',
    q: 'The Greeks called this mountainside sanctuary the navel of the world.',
    s: 'A priestess breathed fumes rising through the rock and answered questions in riddles. Geologists later found two faults crossing beneath the temple, releasing ethylene.' },
  { n: 'Knossos', c: 'Greece', lat: 35.2980, lon: 25.1630, d: 4, r: 'Europe',
    q: 'A palace with 1,300 rooms that gave Europe the legend of a labyrinth.',
    s: 'Arthur Evans excavated and heavily reconstructed it from 1900, inventing much of what visitors see. Its script, Linear A, is still undeciphered.' },
  { n: 'Waterloo', c: 'Belgium', lat: 50.6802, lon: 4.4120, d: 3, r: 'Europe',
    q: 'A hundred days of comeback ended in a muddy field here on 18 June 1815.',
    s: 'Rain the night before delayed the French attack and gave the Prussians time to arrive. Napoleon was exiled to the South Atlantic and died there six years later.' },
  { n: 'Verdun', c: 'France', lat: 49.1594, lon: 5.3831, d: 4, r: 'Europe',
    q: 'A ten-month battle in 1916 left nine villages that were never rebuilt.',
    s: 'They are still marked on maps as "died for France". An ossuary holds the bones of 130,000 unidentified soldiers from both sides.' },
  { n: 'Ieper', c: 'Belgium', lat: 50.8509, lon: 2.8857, d: 4, r: 'Europe',
    q: 'Chlorine gas was first used as a weapon on a large scale outside this town in 1915.',
    s: 'The Last Post has been sounded under the Menin Gate nearly every evening since 1928. English soldiers called the town Wipers.' },
  { n: 'Guernica', c: 'Spain', lat: 43.3167, lon: -2.6796, d: 4, r: 'Europe',
    q: 'A Basque market town bombed on a busy afternoon in 1937 as a test of a new tactic.',
    s: 'The Condor Legion attacked civilians deliberately. Picasso painted his response in a month; for decades he refused to let it go to Spain while Franco lived.' },
  { n: 'Thermopylae', c: 'Greece', lat: 38.7961, lon: 22.5361, d: 4, r: 'Europe',
    q: 'A narrow coastal pass held for three days in 480 BC by a very small force.',
    s: 'Silt has since pushed the shoreline several kilometres away, so the famous bottleneck is now an inland plain beside a highway.' },
  { n: 'Lascaux', c: 'France', lat: 45.0533, lon: 1.1751, d: 5, r: 'Europe',
    q: 'Four teenagers and a dog found 17,000-year-old paintings down a hole here in 1940.',
    s: 'Visitors’ breath grew algae on the walls, so the cave was closed in 1963 and full-size replicas built next door.' },
  { n: 'Bletchley Park', c: 'United Kingdom', lat: 51.9977, lon: -0.7407, d: 5, r: 'Europe',
    q: 'Nine thousand people worked at this country house and none of them talked about it.',
    s: 'Codebreakers here read Enigma traffic; the secret held until the 1970s. Many of the staff were women, and the machines were destroyed after the war on orders.' },
  { n: 'Longyearbyen', c: 'Norway', lat: 78.2232, lon: 15.6469, d: 5, r: 'Europe',
    q: 'A seed vault sits in permafrost above this Arctic coal town.',
    s: 'The Svalbard vault holds over a million crop samples. Anyone from 40-odd treaty countries may live here without a visa, and you must not leave town unarmed because of polar bears.' },
  { n: 'Tórshavn', c: 'Faeroe Is.', lat: 62.0079, lon: -6.7900, d: 5, r: 'Europe',
    q: 'One of the world’s oldest parliaments has met on this rocky point since about 900.',
    s: 'The Tórshavn Løgting predates most European assemblies. The islands sit between Iceland, Norway and Scotland, and roads run through undersea tunnels with a roundabout in one.' },
  { n: 'Aachen', c: 'Germany', lat: 50.7753, lon: 6.0839, d: 4, r: 'Europe',
    q: 'Charlemagne made his capital at these hot springs and was buried in its chapel.',
    s: 'Thirty German kings were crowned here over 600 years. The octagonal chapel of 805 is still standing inside the later cathedral.' },
  { n: 'Wittenberg', c: 'Germany', lat: 51.8663, lon: 12.6474, d: 5, r: 'Europe',
    q: 'Ninety-five theses about indulgences went up on a church door here in 1517.',
    s: 'Whether Luther actually nailed them is disputed; posting notices on the door was routine. Printing spread them across Germany within weeks.' },
  { n: 'Ravenna', c: 'Italy', lat: 44.4184, lon: 12.2035, d: 5, r: 'Europe',
    q: 'The Western Roman Empire’s last capital, chosen because it was surrounded by marsh.',
    s: 'Its 6th-century mosaics are the best-preserved Byzantine work outside Istanbul. Dante died here in exile and is still buried here, not in Florence.' },
  { n: 'Kaliningrad', c: 'Russia', lat: 54.7104, lon: 20.4522, d: 5, r: 'Europe',
    q: 'A Russian region with no land border to Russia, once famous for seven bridges.',
    s: 'As Königsberg it gave Euler the bridge problem that founded graph theory, and it was Kant’s home city; he never left it.' },
  { n: 'Murmansk', c: 'Russia', lat: 68.9585, lon: 33.0827, d: 5, r: 'Europe',
    q: 'The largest city above the Arctic Circle, ice-free thanks to a warm current.',
    s: 'The North Atlantic Drift keeps the port open all year, which made it the destination for Arctic convoys carrying Allied supplies from 1941.' },

  /* ------------------------------------------------------------------ Asia */
  { n: 'Tokyo', c: 'Japan', lat: 35.6895, lon: 139.6917, d: 1, r: 'Asia',
    q: 'An earthquake and firestorm destroyed this city in 1923, and bombing finished the job in 1945.',
    s: 'It has been flattened twice in one lifetime and rebuilt both times. The greater metropolitan area is the largest human settlement that has ever existed.' },
  { n: 'Beijing', c: 'China', lat: 39.9042, lon: 116.4074, d: 1, r: 'Asia',
    q: 'A palace complex of 980 buildings here was off-limits to the public for 500 years.',
    s: 'The Forbidden City housed 24 emperors. The last of them, Puyi, later bought a ticket to visit his own home as an ordinary citizen.' },
  { n: 'Shanghai', c: 'China', lat: 31.2304, lon: 121.4737, d: 1, r: 'Asia',
    q: 'A muddy fishing town forced open by treaty in 1842 became Asia’s money capital.',
    s: 'Its foreign concessions ran their own laws and police. In 1938–41 it admitted around 20,000 Jewish refugees when almost nowhere else would.' },
  { n: 'Hong Kong', c: 'Hong Kong', lat: 22.3193, lon: 114.1694, d: 2, r: 'Asia',
    q: 'A 99-year lease signed in 1898 expired at midnight on 30 June 1997.',
    s: 'Britain held the island outright but not the New Territories, and the colony could not survive without them — so the whole thing went back.' },
  { n: 'Kyoto', c: 'Japan', lat: 35.0116, lon: 135.7681, d: 2, r: 'Asia',
    q: 'This capital of eleven centuries was struck off the atomic target list by one man.',
    s: 'US Secretary of War Henry Stimson had honeymooned there and insisted it be spared. Nagasaki took its place on the second mission.' },
  { n: 'Hiroshima', c: 'Japan', lat: 34.3853, lon: 132.4553, d: 2, r: 'Asia',
    q: 'At 8:15 on 6 August 1945 a bomb detonated 580 metres above this city.',
    s: 'One domed building almost directly beneath the blast stayed standing because the force came straight down. It was left as it was, as a memorial.' },
  { n: 'Nagasaki', c: 'Japan', lat: 32.7503, lon: 129.8779, d: 3, r: 'Asia',
    q: 'Cloud over the primary target sent a bomber to its secondary on 9 August 1945.',
    s: 'Kokura was covered, so the aircraft turned here. Hills contained the blast, which is why casualties were lower despite a more powerful weapon.' },
  { n: 'Seoul', c: 'South Korea', lat: 37.5665, lon: 126.9780, d: 1, r: 'Asia',
    q: 'This capital changed hands four times in the first year of a war that began in 1950.',
    s: 'It sits about 50 km from the border, within artillery range of it. The war ended in an armistice, not a treaty, so it is technically still ongoing.' },
  { n: 'Pyongyang', c: 'North Korea', lat: 39.0392, lon: 125.7625, d: 3, r: 'Asia',
    q: 'A capital with a 105-storey pyramid hotel that stood empty for over thirty years.',
    s: 'The Ryugyong was topped out in 1992, glazed in 2011, and has still never opened. The city was almost entirely rebuilt after 1953.' },
  { n: 'Taipei', c: 'Taiwan', lat: 25.0330, lon: 121.5654, d: 2, r: 'Asia',
    q: 'A government retreated to this island in 1949 and brought the national treasures with it.',
    s: 'Nearly 700,000 imperial artefacts came over from Beijing. The museum here rotates its collection because there is far too much of it to show at once.' },
  { n: 'Singapore', c: 'Singapore', lat: 1.3521, lon: 103.8198, d: 2, r: 'Asia',
    q: 'This country was expelled from a federation in 1965 and its leader wept on television.',
    s: 'Lee Kuan Yew called it a moment of anguish. The island had no natural resources and imported its drinking water; it now has one of the world’s highest GDPs per head.' },
  { n: 'Bangkok', c: 'Thailand', lat: 13.7563, lon: 100.5018, d: 2, r: 'Asia',
    q: 'Its ceremonial name runs to 168 letters and is in the record books as the longest.',
    s: 'Locals call it Krung Thep, "city of angels" — the rest of the name lists its gods and jewels. It sinks about a centimetre a year.' },
  { n: 'Hanoi', c: 'Vietnam', lat: 21.0278, lon: 105.8342, d: 2, r: 'Asia',
    q: 'A declaration of independence read here in 1945 opened by quoting Thomas Jefferson.',
    s: 'Ho Chi Minh borrowed the American phrasing deliberately. The city celebrated its thousandth birthday in 2010.' },
  { n: 'Ho Chi Minh City', c: 'Vietnam', lat: 10.8231, lon: 106.6297, d: 3, r: 'Asia',
    q: 'A helicopter lifted off an apartment roof here on 30 April 1975 in front of a photographer.',
    s: 'The famous image is not the US embassy but a CIA building on Gia Long Street. Tanks came through the palace gates the same morning.' },
  { n: 'Angkor', c: 'Cambodia', lat: 13.4125, lon: 103.8670, d: 3, r: 'Asia',
    q: 'A temple city here may have held 750,000 people when London held 20,000.',
    s: 'Lidar surveys revealed a vast grid of canals and suburbs under the forest. The main temple is the only building on any national flag.' },
  { n: 'Phnom Penh', c: 'Cambodia', lat: 11.5564, lon: 104.9282, d: 3, r: 'Asia',
    q: 'This capital was emptied of its two million people in three days in April 1975.',
    s: 'The Khmer Rouge declared Year Zero and marched everyone into the countryside. A former school in the city became prison S-21, where 12,000 died.' },
  { n: 'Yangon', c: 'Myanmar', lat: 16.8661, lon: 96.1951, d: 4, r: 'Asia',
    q: 'This city lost its capital status overnight in 2005 to a purpose-built inland city.',
    s: 'Ministries were ordered to move to Naypyidaw at short notice, on astrologers’ advice by some accounts. A gilded stupa here is said to hold eight of the Buddha’s hairs.' },
  { n: 'Bagan', c: 'Myanmar', lat: 21.1717, lon: 94.8585, d: 5, r: 'Asia',
    q: 'A plain holding over 2,000 brick temples built in a 250-year building spree.',
    s: 'More than 10,000 were raised between the 11th and 13th centuries before the Mongols arrived. Earthquakes have knocked down a good share since.' },
  { n: 'Jakarta', c: 'Indonesia', lat: -6.2088, lon: 106.8456, d: 2, r: 'Asia',
    q: 'A capital sinking so fast that the government voted to build a replacement on another island.',
    s: 'Parts of it drop 25 cm a year as groundwater is pumped out; around 40% is below sea level. The new capital, Nusantara, is going up in Borneo.' },
  { n: 'Borobudur', c: 'Indonesia', lat: -7.6079, lon: 110.2038, d: 5, r: 'Asia',
    q: 'The largest Buddhist temple on Earth, abandoned for centuries under ash and jungle.',
    s: 'Built around 800 and forgotten after the population shifted east, it was cleared under Raffles in 1814. Walking its nine levels is a scripted pilgrimage in stone.' },
  { n: 'Krakatoa', c: 'Indonesia', lat: -6.1021, lon: 105.4230, d: 5, r: 'Asia', x: 1,
    q: 'An 1883 explosion here was heard 4,800 km away in Australia.',
    s: 'It is the loudest sound in recorded history; pressure waves circled the globe seven times. A new cone, Anak Krakatau, rose from the sea in 1927.' },
  { n: 'Manila', c: 'Philippines', lat: 14.5995, lon: 120.9842, d: 2, r: 'Asia',
    q: 'Galleons ran from this port to Acapulco once a year for 250 years.',
    s: 'The Manila galleons carried Chinese silk east and Mexican silver west, the first regular trade route across the Pacific.' },
  { n: 'Kuala Lumpur', c: 'Malaysia', lat: 3.1390, lon: 101.6869, d: 2, r: 'Asia',
    q: 'Twin towers here held the tallest-building record from 1998 to 2004.',
    s: 'Two consortiums built one tower each and raced; the Korean team started late and finished first. The name means "muddy confluence".' },
  { n: 'Malacca', c: 'Malaysia', lat: 2.1896, lon: 102.2501, d: 5, r: 'Asia',
    q: 'Whoever held this strait held the sea route between India and China.',
    s: 'Portuguese in 1511, Dutch in 1641, British in 1824 — each took the town for the chokepoint. A quarter of world trade still passes through the strait.' },
  { n: 'Ulaanbaatar', c: 'Mongolia', lat: 47.8864, lon: 106.9057, d: 3, r: 'Asia',
    q: 'The coldest capital city in the world, and it moved location 28 times before settling.',
    s: 'It began as a mobile monastery town. Winter means burning coal in the ger districts, giving it some of the worst air quality anywhere.' },
  { n: 'Lhasa', c: 'China', lat: 29.6520, lon: 91.1721, d: 4, r: 'Asia',
    q: 'A thirteen-storey palace here has 1,000 rooms and sits at 3,700 metres.',
    s: 'The Potala was the Dalai Lama’s winter residence until 1959. Visitors routinely need a day or two to acclimatise before climbing the steps.' },
  { n: 'Kashgar', c: 'China', lat: 39.4704, lon: 75.9898, d: 5, r: 'Asia',
    q: 'The oasis where the northern and southern Silk Road routes met again.',
    s: 'It is closer to Baghdad than to Beijing, and its Sunday market has run for roughly two millennia.' },
  { n: 'Xi’an', c: 'China', lat: 34.3416, lon: 108.9398, d: 3, r: 'Asia',
    q: 'Farmers digging a well in 1974 struck a life-sized clay soldier.',
    s: 'They had found an army of about 8,000 guarding the first emperor’s tomb. The tomb mound itself is still unexcavated, reportedly ringed by rivers of mercury.' },
  { n: 'Chengdu', c: 'China', lat: 30.5728, lon: 104.0668, d: 4, r: 'Asia',
    q: 'The world’s first paper money was issued in this region in the 11th century.',
    s: 'Song-dynasty merchants used printed notes rather than haul copper coin. The city is now the main base for giant panda breeding.' },
  { n: 'Harbin', c: 'China', lat: 45.8038, lon: 126.5350, d: 5, r: 'Asia',
    q: 'A Chinese city built by a Russian railway, with a festival of buildings made from ice.',
    s: 'The Trans-Manchurian line created it in 1898, which is why it has onion domes. January blocks are cut from the Songhua river.' },
  { n: 'Delhi', c: 'India', lat: 28.6139, lon: 77.2090, d: 1, r: 'Asia',
    q: 'An iron pillar standing here since about AD 400 has barely rusted.',
    s: 'Its phosphorus content forms a protective film — early metallurgy that still puzzles people. Seven or more cities have been built on this site.' },
  { n: 'Mumbai', c: 'India', lat: 19.0760, lon: 72.8777, d: 2, r: 'Asia',
    q: 'Seven islands were joined by land reclamation into one city, which came to Britain as a dowry.',
    s: 'Catherine of Braganza brought it to Charles II in 1661; he leased it to the East India Company for £10 a year. Its lunchbox carriers deliver 200,000 meals a day by hand.' },
  { n: 'Agra', c: 'India', lat: 27.1751, lon: 78.0421, d: 2, r: 'Asia',
    q: 'A mausoleum here was built for a wife who died giving birth to her fourteenth child.',
    s: 'Shah Jahan spent 22 years on it. The four minarets lean very slightly outward so they would fall away from the tomb in an earthquake.' },
  { n: 'Varanasi', c: 'India', lat: 25.3176, lon: 82.9739, d: 3, r: 'Asia',
    q: 'One of the oldest continuously inhabited cities on Earth, where Hindus come to die.',
    s: 'Cremation fires on the ghats have burned without going out for centuries. Twain wrote it looked older than history itself.' },
  { n: 'Amritsar', c: 'India', lat: 31.6340, lon: 74.8723, d: 4, r: 'Asia',
    q: 'A gilded temple here serves free meals to about 100,000 people every day.',
    s: 'The Golden Temple’s kitchen is the world’s largest, run by volunteers. Troops fired on a penned-in crowd in the city in 1919, killing hundreds.' },
  { n: 'Kolkata', c: 'India', lat: 22.5726, lon: 88.3639, d: 3, r: 'Asia',
    q: 'The capital of British India until the government packed up and left in 1911.',
    s: 'The move to Delhi was announced by George V at a durbar. The city still runs a tram network started in 1873.' },
  { n: 'Bengaluru', c: 'India', lat: 12.9716, lon: 77.5946, d: 3, r: 'Asia',
    q: 'A garden city at 900 metres that became the back office of the world.',
    s: 'Its altitude gives it mild weather year-round, which is partly why the software industry settled here in the 1990s.' },
  { n: 'Kathmandu', c: 'Nepal', lat: 27.7172, lon: 85.3240, d: 3, r: 'Asia',
    q: 'A living goddess is chosen from young girls in this city and retires at puberty.',
    s: 'The Kumari is selected by strict physical criteria and appears in public only for festivals. A 2015 earthquake destroyed several of the valley’s temple squares.' },
  { n: 'Mount Everest', c: 'Nepal', lat: 27.9881, lon: 86.9250, d: 3, r: 'Asia', x: 1,
    q: 'A 1955 survey settled its height at 8,848 m; the summit itself is marine limestone.',
    s: 'The rock at the top formed on an ancient seabed. The mountain grows a few millimetres a year as India keeps pushing north.' },
  { n: 'Colombo', c: 'Sri Lanka', lat: 6.9271, lon: 79.8612, d: 4, r: 'Asia',
    q: 'The commercial capital of an island whose official capital is a suburb nobody can spell.',
    s: 'Parliament sits at Sri Jayawardenepura Kotte. The island supplied the world’s cinnamon and was called Serendib, root of the word serendipity.' },
  { n: 'Sigiriya', c: 'Sri Lanka', lat: 7.9570, lon: 80.7603, d: 5, r: 'Asia',
    q: 'A king built his palace on top of a 180-metre rock plug to hide from his brother.',
    s: 'Kasyapa took the throne by walling up his father alive, then ruled from the summit for 18 years. The stairway once climbed through a giant brick lion’s throat.' },
  { n: 'Dhaka', c: 'Bangladesh', lat: 23.8103, lon: 90.4125, d: 3, r: 'Asia',
    q: 'The most densely populated large city on Earth, on a delta fed by three great rivers.',
    s: 'The Ganges, Brahmaputra and Meghna all discharge past it. It was once famous for muslin so fine it was called woven air.' },
  { n: 'Karachi', c: 'Pakistan', lat: 24.8607, lon: 67.0011, d: 3, r: 'Asia',
    q: 'A fishing village of 14,000 in 1840 that is now a city of over 15 million.',
    s: 'It was Pakistan’s first capital and remains its port and money centre; the capital moved to a purpose-built city in the north in the 1960s.' },
  { n: 'Mohenjo-daro', c: 'Pakistan', lat: 27.3294, lon: 68.1386, d: 5, r: 'Asia',
    q: 'A city with brick sewers and grid streets, built 4,500 years ago and unknown until 1922.',
    s: 'Its civilisation ran across a bigger area than Egypt and Mesopotamia combined, left no royal tombs, and its writing is still unread.' },
  { n: 'Samarkand', c: 'Uzbekistan', lat: 39.6270, lon: 66.9750, d: 4, r: 'Asia',
    q: 'Timur made this his capital and dragged craftsmen here from every city he sacked.',
    s: 'His grandson Ulugh Beg built an observatory that measured the year to within a minute. The tiled square, the Registan, is the great sight of Central Asia.' },
  { n: 'Bukhara', c: 'Uzbekistan', lat: 39.7747, lon: 64.4286, d: 5, r: 'Asia',
    q: 'A Silk Road city whose emir kept two British officers in a pit full of vermin.',
    s: 'Stoddart and Conolly were executed in 1842 during the Great Game. The old town has over 140 protected monuments in a few square kilometres.' },
  { n: 'Tashkent', c: 'Uzbekistan', lat: 41.2995, lon: 69.2401, d: 4, r: 'Asia',
    q: 'A 1966 earthquake flattened this capital and the whole USSR came to rebuild it.',
    s: 'Crews from every republic put up the new city, giving it wide avenues and a metro with chandeliers that doubled as a bomb shelter.' },
  { n: 'Almaty', c: 'Kazakhstan', lat: 43.2220, lon: 76.8512, d: 4, r: 'Asia',
    q: 'This city lost capital status in 1997 to a windswept town 1,200 km north.',
    s: 'The name means "father of apples", and the region is the genetic origin of the domestic apple. The new capital gets to −40 °C.' },
  { n: 'Baikonur', c: 'Kazakhstan', lat: 45.9646, lon: 63.3052, d: 5, r: 'Asia',
    q: 'Sputnik and Gagarin both left the ground from this leased patch of steppe.',
    s: 'Russia rents the cosmodrome from Kazakhstan for about $115 million a year. It was named after a town 320 km away to confuse foreign intelligence.' },
  { n: 'Bishkek', c: 'Kyrgyzstan', lat: 42.8746, lon: 74.5698, d: 5, r: 'Asia',
    q: 'A capital under snow-capped peaks in a country that is 90% mountains.',
    s: 'A large alpine lake nearby, Issyk-Kul, never freezes despite the altitude. The country still practises eagle hunting on horseback.' },
  { n: 'Kabul', c: 'Afghanistan', lat: 34.5553, lon: 69.2075, d: 3, r: 'Asia',
    q: 'A single British survivor rode into Jalalabad in 1842 from a retreating army of 16,000.',
    s: 'Assistant surgeon William Brydon was believed the only man to complete the retreat from this city. The place sits in a bowl at 1,790 m ringed by mountains.' },
  { n: 'Bamiyan', c: 'Afghanistan', lat: 34.8266, lon: 67.8267, d: 5, r: 'Asia',
    q: 'Two standing Buddhas carved into a cliff in the 6th century were dynamited in 2001.',
    s: 'The larger was 55 m tall. The empty niches remain, and fragments are stored in the hope of rebuilding one.' },
  { n: 'Vladivostok', c: 'Russia', lat: 43.1155, lon: 131.8855, d: 4, r: 'Asia',
    q: 'The eastern end of a railway line 9,289 km long.',
    s: 'The Trans-Siberian takes about seven days and crosses eight time zones. The city was closed to foreigners until 1991.' },
  { n: 'Lake Baikal', c: 'Russia', lat: 53.5587, lon: 108.1650, d: 4, r: 'Asia',
    q: 'One lake holding a fifth of the world’s unfrozen fresh water.',
    s: 'It is 1,642 m deep and 25 million years old, with a freshwater seal found nowhere else. In winter the ice is thick enough to drive on.' },
  { n: 'Yakutsk', c: 'Russia', lat: 62.0355, lon: 129.6755, d: 5, r: 'Asia',
    q: 'The coldest city on Earth, built entirely on stilts driven into permafrost.',
    s: 'Buildings stand clear of the ground so their heat cannot thaw it. Winter temperatures reach −50 °C and cars are often left running all day.' },
  { n: 'Tunguska', c: 'Russia', lat: 60.8860, lon: 101.8940, d: 5, r: 'Asia',
    q: 'Something exploded over this forest in 1908 and flattened 80 million trees.',
    s: 'The blast was around 10–15 megatons with no crater, so it was almost certainly an air burst. The first scientific expedition did not arrive until 1927.' },

  /* ---------------------------------------------------------- Middle East */
  { n: 'Jerusalem', c: 'Israel', lat: 31.7683, lon: 35.2137, d: 2, r: 'Middle East', x: 1,
    q: 'A walled old city of one square kilometre, divided into four quarters.',
    s: 'It holds the holiest site in Judaism, the third holiest in Islam and the traditional site of the crucifixion. A Muslim family has kept the keys to the Holy Sepulchre since the 12th century.' },
  { n: 'Mecca', c: 'Saudi Arabia', lat: 21.4225, lon: 39.8262, d: 2, r: 'Middle East',
    q: 'Every mosque on Earth points at one building in this valley.',
    s: 'The hajj brings around two million people a year to a city non-Muslims may not enter. The surrounding hills are now ringed with skyscrapers.' },
  { n: 'Riyadh', c: 'Saudi Arabia', lat: 24.7136, lon: 46.6753, d: 3, r: 'Middle East',
    q: 'A desert capital of eight million with no permanent river.',
    s: 'Its water comes largely from desalination pumped 400 km inland from the Gulf. The name means "the gardens", after the oases the city grew from.' },
  { n: 'Dubai', c: 'United Arab Emirates', lat: 25.2048, lon: 55.2708, d: 2, r: 'Middle East',
    q: 'A pearl-diving town that put up the world’s tallest building in 2010.',
    s: 'The Burj Khalifa is 828 m and was renamed at the opening after Abu Dhabi’s ruler bailed the project out. Oil is only a small share of the emirate’s economy.' },
  { n: 'Doha', c: 'Qatar', lat: 25.2854, lon: 51.5310, d: 3, r: 'Middle East',
    q: 'A peninsula capital that air-conditioned open-air stadiums for a winter World Cup.',
    s: 'The 2022 tournament moved to November to dodge 45 °C summers. The country sits on the world’s third-largest natural gas reserves.' },
  { n: 'Kuwait City', c: 'Kuwait', lat: 29.3759, lon: 47.9774, d: 4, r: 'Middle East',
    q: 'Retreating troops set 600 oil wells alight here in 1991.',
    s: 'The fires burned for ten months and turned day into night; Red Adair’s teams were brought in to cap them.' },
  { n: 'Muscat', c: 'Oman', lat: 23.5880, lon: 58.3829, d: 4, r: 'Middle East',
    q: 'A capital squeezed between sheer brown mountains and the sea, with a ban on tall buildings.',
    s: 'Nothing may rise above a low limit outside the business district. This country once ruled Zanzibar, and briefly had its capital there.' },
  { n: 'Sanaa', c: 'Yemen', lat: 15.3694, lon: 44.1910, d: 5, r: 'Middle East',
    q: 'Tower houses of mud brick eight storeys high, decorated in white gypsum, in a city 2,500 years old.',
    s: 'Legend credits its founding to Noah’s son Shem. It sits at 2,250 m, one of the highest capitals in the world.' },
  { n: 'Baghdad', c: 'Iraq', lat: 33.3152, lon: 44.3661, d: 2, r: 'Middle East',
    q: 'A perfectly round city founded in 762 became the world’s largest, then the Mongols came.',
    s: 'Its House of Wisdom preserved and extended Greek learning. In 1258 the Mongols destroyed the libraries; the Tigris is said to have run black with ink.' },
  { n: 'Babylon', c: 'Iraq', lat: 32.5364, lon: 44.4208, d: 4, r: 'Middle East',
    q: 'A law code carved on a stone pillar here around 1750 BC survives nearly complete.',
    s: 'Hammurabi’s laws set prices, wages and punishments. Saddam Hussein rebuilt walls on the site with bricks stamped with his own name.' },
  { n: 'Ur', c: 'Iraq', lat: 30.9626, lon: 46.1030, d: 5, r: 'Middle East',
    q: 'A Sumerian city with a stepped ziggurat, on a river channel that has since moved away.',
    s: 'Leonard Woolley dug up royal tombs here in the 1920s, complete with attendants who had been buried alive. It was a seaport once; the Gulf has retreated 200 km.' },
  { n: 'Tehran', c: 'Iran', lat: 35.6892, lon: 51.3890, d: 2, r: 'Middle East',
    q: 'An embassy in this capital was seized in November 1979 and held for 444 days.',
    s: 'Fifty-two Americans were released the day Reagan was inaugurated. The city sits under a 5,600 m volcano and is smog-trapped by mountains.' },
  { n: 'Persepolis', c: 'Iran', lat: 29.9354, lon: 52.8916, d: 4, r: 'Middle East',
    q: 'Alexander burned this ceremonial capital in 330 BC, possibly at a drunken party.',
    s: 'The fire baked its clay archives hard, preserving them. Carved stairways show delegations from across the empire bringing tribute.' },
  { n: 'Isfahan', c: 'Iran', lat: 32.6546, lon: 51.6680, d: 4, r: 'Middle East',
    q: 'A 17th-century capital whose central square is one of the largest on Earth.',
    s: 'The saying went "Isfahan is half the world". Its bridges double as tea houses, and one has 33 arches.' },
  { n: 'Damascus', c: 'Syria', lat: 33.5138, lon: 36.2765, d: 3, r: 'Middle East',
    q: 'A claimant for the oldest continuously inhabited city, on a river fed by melting snow.',
    s: 'Its Straight Street appears in the Book of Acts. The Umayyad Mosque was a Roman temple and then a church before 705.' },
  { n: 'Palmyra', c: 'Syria', lat: 34.5511, lon: 38.2667, d: 5, r: 'Middle East',
    q: 'A caravan oasis whose queen rebelled against Rome and briefly ran Egypt.',
    s: 'Zenobia was paraded through Rome in gold chains in 274. ISIS blew up the temple of Bel and murdered the 82-year-old chief archaeologist in 2015.' },
  { n: 'Beirut', c: 'Lebanon', lat: 33.8938, lon: 35.5018, d: 3, r: 'Middle East',
    q: '2,750 tonnes of ammonium nitrate stored in a port shed exploded here in August 2020.',
    s: 'The blast was among the largest non-nuclear explosions ever recorded and was heard in Cyprus. The cargo had sat confiscated for six years.' },
  { n: 'Baalbek', c: 'Lebanon', lat: 34.0059, lon: 36.2039, d: 5, r: 'Middle East',
    q: 'Roman temple foundations here include cut stones weighing 800 tonnes.',
    s: 'Nobody is certain how the trilithon blocks were moved. A larger one, 1,650 tonnes, still lies in the quarry.' },
  { n: 'Petra', c: 'Jordan', lat: 30.3285, lon: 35.4444, d: 3, r: 'Middle East',
    q: 'A city carved into rose-coloured cliffs, reached through a 1.2 km crack in the rock.',
    s: 'The Nabataeans controlled the incense trade and engineered dams and cisterns in a desert. It was unknown to Europeans until 1812.' },
  { n: 'Amman', c: 'Jordan', lat: 31.9454, lon: 35.9284, d: 4, r: 'Middle East',
    q: 'A capital built across nineteen hills, called Philadelphia in Roman times.',
    s: 'Streets are still named by circle numbers running up the hills. Its population multiplied many times over through successive waves of refugees.' },
  { n: 'Ankara', c: 'Turkey', lat: 39.9334, lon: 32.8597, d: 3, r: 'Middle East',
    q: 'Atatürk made this inland town the capital in 1923 instead of the obvious choice.',
    s: 'It was defensible and far from foreign fleets. The angora goat, rabbit and cat are all named after the city.' },
  { n: 'Göbekli Tepe', c: 'Turkey', lat: 37.2231, lon: 38.9224, d: 5, r: 'Middle East',
    q: 'Carved stone pillars raised here around 9500 BC, before pottery or farming.',
    s: 'It is roughly 6,000 years older than Stonehenge and upended the assumption that farming came before monuments. Most of the site is still buried.' },
  { n: 'Troy', c: 'Turkey', lat: 39.9575, lon: 26.2389, d: 5, r: 'Middle East',
    q: 'Heinrich Schliemann dug straight through nine cities here looking for one from a poem.',
    s: 'His trench destroyed much of the layer he was actually seeking. The site is now several kilometres inland as the bay silted up.' },
  { n: 'Ephesus', c: 'Turkey', lat: 37.9398, lon: 27.3419, d: 4, r: 'Middle East',
    q: 'A temple here was burned by a man who wanted to be remembered for something.',
    s: 'Herostratus torched the Temple of Artemis in 356 BC; the city banned anyone from speaking his name, which plainly failed. Its library facade still stands.' },
  { n: 'Cappadocia', c: 'Turkey', lat: 38.6431, lon: 34.8289, d: 4, r: 'Middle East',
    q: 'Whole cities were dug eight levels down into soft volcanic rock here.',
    s: 'Derinkuyu could shelter 20,000 people with stables and wineries, sealed by rolling stone doors. The surface is a forest of eroded "fairy chimneys".' },
  { n: 'Gallipoli', c: 'Turkey', lat: 40.2270, lon: 26.4058, d: 4, r: 'Middle East',
    q: 'A landing on this peninsula in April 1915 became eight months of stalemate on cliffs.',
    s: 'It is the founding national story of both Australia and New Zealand, and made the reputation of the Ottoman commander who became Atatürk.' },
  { n: 'Yerevan', c: 'Armenia', lat: 40.1792, lon: 44.4991, d: 5, r: 'Middle East',
    q: 'A pink-tufa capital that looks at a sacred mountain lying in another country.',
    s: 'Ararat is on Armenia’s coat of arms but inside Turkey. The city was founded in 782 BC, making it older than Rome.' },
  { n: 'Baku', c: 'Azerbaijan', lat: 40.4093, lon: 49.8671, d: 4, r: 'Middle East',
    q: 'Half the world’s oil came from this city in 1900.',
    s: 'Ground here seeps flammable gas, which sustained fire temples for centuries. It sits 28 m below sea level on the Caspian.' },
  { n: 'Tbilisi', c: 'Georgia', lat: 41.7151, lon: 44.8271, d: 4, r: 'Middle East',
    q: 'A king founded this capital at hot springs after a wounded pheasant fell into one.',
    s: 'The name comes from the word for warm. Wine has been made in the surrounding country in buried clay vessels for 8,000 years.' },

  /* ---------------------------------------------------------------- Africa */
  { n: 'Cairo', c: 'Egypt', lat: 30.0444, lon: 31.2357, d: 1, r: 'Africa',
    q: 'The largest city in Africa and the Arab world, beside the only surviving ancient wonder.',
    s: 'Al-Azhar, founded in 970, is one of the oldest continuously operating universities anywhere. The city’s traffic is famous enough to have its own genre of jokes.' },
  { n: 'Giza', c: 'Egypt', lat: 29.9792, lon: 31.1342, d: 2, r: 'Africa',
    q: 'A pyramid here was the tallest structure on Earth for about 3,800 years.',
    s: 'Khufu’s was 146.6 m and held the record until Lincoln Cathedral. The blocks were cut with copper tools and moved without wheels or pulleys.' },
  { n: 'Luxor', c: 'Egypt', lat: 25.6872, lon: 32.6396, d: 3, r: 'Africa',
    q: 'Howard Carter found sixteen steps under rubble here in November 1922.',
    s: 'Tutankhamun’s tomb was the only near-intact royal burial found in the Valley of the Kings. Carter had been digging for six seasons and was on his last funded year.' },
  { n: 'Alexandria', c: 'Egypt', lat: 31.2001, lon: 29.9187, d: 3, r: 'Africa',
    q: 'A lighthouse and the ancient world’s greatest library both stood in this port.',
    s: 'The Pharos survived until earthquakes toppled it in the 1300s; its stones went into a fort on the same spot. Much of the ancient royal quarter is now underwater.' },
  { n: 'Abu Simbel', c: 'Egypt', lat: 22.3372, lon: 31.6258, d: 5, r: 'Africa',
    q: 'Two temples here were cut into 1,000 blocks and moved uphill in the 1960s.',
    s: 'A rising reservoir behind the Aswan High Dam would have drowned them. The reassembly kept the alignment that lights the inner sanctuary twice a year.' },
  { n: 'Marrakesh', c: 'Morocco', lat: 31.6295, lon: -7.9811, d: 2, r: 'Africa',
    q: 'A red-walled city whose main square fills every evening with food stalls and storytellers.',
    s: 'Jemaa el-Fnaa’s oral performers are recognised by UNESCO as living heritage. The country’s name in Persian and Turkish still derives from this city.' },
  { n: 'Fez', c: 'Morocco', lat: 34.0181, lon: -5.0078, d: 4, r: 'Africa',
    q: 'The world’s oldest continuously operating university was founded here in 859 by a woman.',
    s: 'Fatima al-Fihri endowed al-Qarawiyyin. The old medina is the largest car-free urban area in the world, and its tanneries still use pigeon droppings.' },
  { n: 'Tangier', c: 'Morocco', lat: 35.7595, lon: -5.8340, d: 4, r: 'Africa',
    q: 'This port was run by nine countries at once as an international zone until 1956.',
    s: 'The arrangement drew writers, spies and tax exiles. Africa and Europe are 14 km apart at the strait it guards.' },
  { n: 'Algiers', c: 'Algeria', lat: 36.7538, lon: 3.0588, d: 3, r: 'Africa',
    q: 'A brutal urban campaign here from 1956–57 became the standard text on insurgency.',
    s: 'Pontecorvo’s 1966 film about it was screened at the Pentagon in 2003. The old casbah tumbles down the hillside above the bay.' },
  { n: 'Carthage', c: 'Tunisia', lat: 36.8528, lon: 10.3233, d: 4, r: 'Africa',
    q: 'Rome razed this city in 146 BC, then rebuilt it as its own African capital.',
    s: 'The story that the Romans salted the earth appears nowhere in ancient sources. Hannibal set out from here to cross the Alps with elephants.' },
  { n: 'Leptis Magna', c: 'Libya', lat: 32.6386, lon: 14.2914, d: 5, r: 'Africa',
    q: 'A Roman city buried by sand for centuries, which is why it is so well preserved.',
    s: 'Emperor Septimius Severus was born here and rebuilt it lavishly. Some of its columns were shipped to England in the 1800s and stand in Windsor Great Park.' },
  { n: 'Timbuktu', c: 'Mali', lat: 16.7735, lon: -3.0074, d: 4, r: 'Africa',
    q: 'A byword for remoteness that was once a university city with 700,000 manuscripts.',
    s: 'Salt came south, gold went north, and scholarship grew in between. Families smuggled manuscripts out by boat and motorbike when militants occupied the town in 2012.' },
  { n: 'Dakar', c: 'Senegal', lat: 14.7167, lon: -17.4677, d: 3, r: 'Africa',
    q: 'The westernmost city on the African mainland, and the old finish line of a desert rally.',
    s: 'Gorée Island lies just offshore, a slave-trade site and memorial. The rally moved to South America in 2009 over security, then to Saudi Arabia.' },
  { n: 'Accra', c: 'Ghana', lat: 5.6037, lon: -0.1870, d: 3, r: 'Africa',
    q: 'In 1957 this became the capital of the first sub-Saharan colony to win independence.',
    s: 'Kwame Nkrumah declared it at midnight in a field now called Black Star Square. The country was formerly the Gold Coast.' },
  { n: 'Elmina', c: 'Ghana', lat: 5.0846, lon: -1.3506, d: 5, r: 'Africa',
    q: 'The oldest European building in sub-Saharan Africa, built by the Portuguese in 1482.',
    s: 'The castle became a slave-trading depot with a "door of no return". It changed hands to the Dutch and then the British before independence.' },
  { n: 'Lagos', c: 'Nigeria', lat: 6.5244, lon: 3.3792, d: 2, r: 'Africa',
    q: 'Africa’s largest city by some counts, and the capital moved away from it in 1991.',
    s: 'Abuja was built inland as a neutral site. This city is projected to be among the world’s largest by 2050, and it is spread across islands and a lagoon.' },
  { n: 'Benin City', c: 'Nigeria', lat: 6.3350, lon: 5.6037, d: 5, r: 'Africa',
    q: 'A British expedition looted thousands of brass plaques from this kingdom’s palace in 1897.',
    s: 'The Benin Bronzes are scattered across Western museums and are now being returned in batches. The city’s earthworks were once the largest earthen structure on Earth.' },
  { n: 'Addis Ababa', c: 'Ethiopia', lat: 9.0320, lon: 38.7469, d: 3, r: 'Africa',
    q: 'The African Union sits in this capital, in the only African country never colonised.',
    s: 'Italy was defeated at Adwa in 1896 and occupied the country only briefly in the 1930s. The country keeps its own 13-month calendar, about seven years behind.' },
  { n: 'Lalibela', c: 'Ethiopia', lat: 12.0317, lon: 39.0473, d: 5, r: 'Africa',
    q: 'Eleven churches here were carved downward out of solid rock in the 12th century.',
    s: 'They were cut as single pieces, roofs first, with drainage trenches around them. Pilgrims still use them; they are not ruins.' },
  { n: 'Asmara', c: 'Eritrea', lat: 15.3229, lon: 38.9251, d: 5, r: 'Africa',
    q: 'An Italian modernist city at 2,300 m, including a petrol station shaped like a plane.',
    s: 'Mussolini’s planners used it as a design laboratory in the 1930s. The whole centre is a UNESCO site, unusually for 20th-century architecture.' },
  { n: 'Mogadishu', c: 'Somalia', lat: 2.0469, lon: 45.3182, d: 4, r: 'Africa',
    q: 'Two helicopters were shot down over this city on 3 October 1993.',
    s: 'The 15-hour battle that followed pushed the US out of the country and shaped the next decade of intervention policy. The city was a wealthy Indian Ocean trading port for centuries.' },
  { n: 'Nairobi', c: 'Kenya', lat: -1.2921, lon: 36.8219, d: 2, r: 'Africa',
    q: 'A capital with a national park full of lions seven kilometres from downtown.',
    s: 'It began in 1899 as a railway supply depot in a swamp. The name comes from a Maasai phrase meaning cool water.' },
  { n: 'Kilimanjaro', c: 'Tanzania', lat: -3.0674, lon: 37.3556, d: 3, r: 'Africa',
    q: 'The highest free-standing mountain in the world, and you can walk up it.',
    s: 'It is a dormant volcano at 5,895 m with no technical climbing required, though altitude turns back plenty of people. Its glaciers have lost most of their ice since 1912.' },
  { n: 'Olduvai Gorge', c: 'Tanzania', lat: -2.9906, lon: 35.3520, d: 5, r: 'Africa',
    q: 'The Leakeys dug up 1.8-million-year-old hominin remains in this ravine.',
    s: 'The gorge cuts through two million years of layered ash, making it a readable timeline. Footprints nearby at Laetoli show upright walking 3.6 million years ago.' },
  { n: 'Zanzibar', c: 'Tanzania', lat: -6.1659, lon: 39.2026, d: 4, r: 'Africa',
    q: 'This island fought the shortest war in history, lasting about 38 minutes in 1896.',
    s: 'It was the world’s clove capital and a major slave market, ruled from Oman. Freddie Mercury was born here in 1946.' },
  { n: 'Kigali', c: 'Rwanda', lat: -1.9441, lon: 30.0619, d: 4, r: 'Africa',
    q: 'A capital in a country of a thousand hills that bans plastic bags outright.',
    s: 'Bags are confiscated at the airport, and the last Saturday of each month is a national community clean-up. The city is among Africa’s cleanest and safest.' },
  { n: 'Victoria Falls', c: 'Zimbabwe', lat: -17.9243, lon: 25.8572, d: 3, r: 'Africa', x: 1,
    q: 'A curtain of water 1.7 km wide that locals called "the smoke that thunders".',
    s: 'Mosi-oa-Tunya drops into a zigzag gorge cut along old fault lines. Spray rises 400 m and is visible from 50 km away.' },
  { n: 'Great Zimbabwe', c: 'Zimbabwe', lat: -20.2674, lon: 30.9346, d: 5, r: 'Africa',
    q: 'Stone walls eleven metres high built without mortar, which colonial authorities refused to credit locally.',
    s: 'Rhodesian censors pressured archaeologists to attribute it to foreigners. It was built by the Shona from the 11th century, and the modern country took its name.' },
  { n: 'Cape Town', c: 'South Africa', lat: -33.9249, lon: 18.4241, d: 2, r: 'Africa',
    q: 'A flat-topped mountain overlooks the harbour, and a prison island lies in the bay.',
    s: 'Nelson Mandela spent 18 of his 27 prison years on Robben Island. The cape’s floral kingdom is the smallest and richest of the world’s six.' },
  { n: 'Johannesburg', c: 'South Africa', lat: -26.2041, lon: 28.0473, d: 3, r: 'Africa',
    q: 'A city founded in 1886 because someone tripped over a gold reef.',
    s: 'It is the largest city in the world not on a river, lake or coast. Its mine dumps are still being reprocessed for leftover gold.' },
  { n: 'Windhoek', c: 'Namibia', lat: -22.5609, lon: 17.0658, d: 4, r: 'Africa',
    q: 'A capital where German beer purity law is still observed, in a former German colony.',
    s: 'The country is the second least densely populated on Earth. Its coast is lined with shipwrecks and it hosts the world’s oldest desert.' },
  { n: 'Sossusvlei', c: 'Namibia', lat: -24.7280, lon: 15.3457, d: 5, r: 'Africa',
    q: 'Orange dunes up to 300 m tall surround a clay pan of dead camelthorn trees.',
    s: 'The trees at Deadvlei died around 700 years ago and are too dry to rot. The dune sand came down the Orange River and blew inland from the Atlantic coast.' },
  { n: 'Okavango Delta', c: 'Botswana', lat: -19.2833, lon: 22.9000, d: 5, r: 'Africa',
    q: 'A river that ends in the middle of a desert instead of reaching the sea.',
    s: 'Floodwater from Angola arrives here months later, in the dry season, drawing enormous concentrations of game onto a green inland fan.' },
  { n: 'Maseru', c: 'Lesotho', lat: -29.3167, lon: 27.4833, d: 5, r: 'Africa',
    q: 'The capital of the only country entirely above 1,000 metres in elevation.',
    s: 'It is one of three countries completely surrounded by a single other country, and it sells water to its neighbour from mountain dams.' },
  { n: 'Antananarivo', c: 'Madagascar', lat: -18.8792, lon: 47.5079, d: 4, r: 'Africa',
    q: 'The capital of an island whose closest linguistic relatives are 6,000 km away in Borneo.',
    s: 'It was settled by Austronesian sailors around 1,500 years ago. Roughly 90% of its wildlife exists nowhere else.' },
  { n: 'Kinshasa', c: 'Dem. Rep. Congo', lat: -4.4419, lon: 15.2663, d: 3, r: 'Africa',
    q: 'A heavyweight title fight was staged in this city at 4 a.m. in October 1974.',
    s: 'Ali beat Foreman in the Rumble in the Jungle, timed for US television. This city and another capital face each other across the river, the closest pair in the world.' },
  { n: 'Luanda', c: 'Angola', lat: -8.8390, lon: 13.2894, d: 4, r: 'Africa',
    q: 'An oil capital that has repeatedly topped surveys as the most expensive city for expatriates.',
    s: 'Almost everything is imported after a 27-year civil war wrecked local production. It was a major Portuguese slave-trading port for three centuries.' },
  { n: 'Khartoum', c: 'Sudan', lat: 15.5007, lon: 32.5599, d: 4, r: 'Africa',
    q: 'Two rivers meet at this capital, one clear and one silty, and stay visibly separate.',
    s: 'The Blue Nile from Ethiopia and the White Nile from Uganda join here; the Arabic name means elephant’s trunk, after the shape of the confluence.' },
  { n: 'Meroë', c: 'Sudan', lat: 16.9333, lon: 33.7500, d: 5, r: 'Africa',
    q: 'This country has around twice as many pyramids as Egypt does.',
    s: 'The Nubian pyramids are steeper and smaller, about 200 of them. An Italian treasure hunter blew the tops off dozens in the 1830s.' },
  { n: 'Maputo', c: 'Mozambique', lat: -25.9692, lon: 32.5732, d: 5, r: 'Africa',
    q: 'A capital with a railway station designed by an associate of Eiffel’s firm.',
    s: 'The country’s flag is the only national flag with a modern rifle on it. Independence from Portugal came in 1975, followed by 16 years of civil war.' },
  { n: 'Nouakchott', c: 'Mauritania', lat: 18.0735, lon: -15.9582, d: 5, r: 'Africa',
    q: 'A village of a few hundred people in 1958 chosen to be a capital from scratch.',
    s: 'It now holds over a million, with sand encroaching from the east. The country runs one of the world’s longest trains, over two kilometres of iron ore.' },
  { n: 'Bangui', c: 'Central African Rep.', lat: 4.3947, lon: 18.5582, d: 5, r: 'Africa',
    q: 'A capital on a river bend, in a country whose ruler crowned himself emperor in 1977.',
    s: 'Bokassa’s coronation cost a reported third of the national budget, complete with a gilded eagle throne. He was overthrown two years later.' },

  /* --------------------------------------------------------- South America */
  { n: 'Rio de Janeiro', c: 'Brazil', lat: -22.9068, lon: -43.1729, d: 1, r: 'S America',
    q: 'A 38-metre statue on a granite peak here was funded by public donations.',
    s: 'Christ the Redeemer went up in 1931 with a French sculptor and Romanian engineer involved. The city was Portugal’s imperial capital from 1808, the only European capital ever in the Americas.' },
  { n: 'São Paulo', c: 'Brazil', lat: -23.5505, lon: -46.6333, d: 2, r: 'S America',
    q: 'The largest city in the southern hemisphere, with the most helicopters of any city on Earth.',
    s: 'Traffic pushed executives into the air; there are hundreds of rooftop pads. It also has the largest Japanese population outside Japan.' },
  { n: 'Brasília', c: 'Brazil', lat: -15.7939, lon: -47.8828, d: 3, r: 'S America',
    q: 'A capital built from bare savanna in 41 months and inaugurated in 1960.',
    s: 'Costa laid it out in the shape of an aeroplane and Niemeyer designed the buildings. It has almost no street corners in the residential wings.' },
  { n: 'Manaus', c: 'Brazil', lat: -3.1190, lon: -60.0217, d: 4, r: 'S America',
    q: 'Rubber barons built an opera house deep in the rainforest and imported everything for it.',
    s: 'The Amazonas theatre opened in 1896 with Italian marble and French glass. The boom collapsed when smuggled seeds started plantations in Asia.' },
  { n: 'Salvador', c: 'Brazil', lat: -12.9777, lon: -38.5016, d: 4, r: 'S America',
    q: 'Brazil’s first capital and the main port of arrival in the Atlantic slave trade.',
    s: 'More enslaved Africans were brought to Brazil than anywhere else. The city’s food, music and Candomblé religion carry that inheritance directly.' },
  { n: 'Buenos Aires', c: 'Argentina', lat: -34.6037, lon: -58.3816, d: 1, r: 'S America',
    q: 'A crowd filled the square below this city’s pink palace to hear Evita in 1951.',
    s: 'She turned down the vice-presidency there, dying of cancer the next year. The city has more bookshops per person than any other.' },
  { n: 'Ushuaia', c: 'Argentina', lat: -54.8019, lon: -68.3030, d: 4, r: 'S America',
    q: 'The southernmost city in the world, and the usual jumping-off point for Antarctica.',
    s: 'It began as a penal colony chosen for being impossible to escape from. Sunset in midsummer comes after 10 p.m.' },
  { n: 'Mendoza', c: 'Argentina', lat: -32.8895, lon: -68.8458, d: 5, r: 'S America',
    q: 'A desert wine region kept alive by irrigation channels first dug by the Huarpe.',
    s: 'Nearly all Argentine malbec comes from here, at 900–1,500 m under the Andes. Aconcagua, the highest peak outside Asia, is nearby.' },
  { n: 'Santiago', c: 'Chile', lat: -33.4489, lon: -70.6693, d: 2, r: 'S America',
    q: 'Jets bombed the presidential palace in this capital on 11 September 1973.',
    s: 'Allende died inside during Pinochet’s coup. The city sits in a bowl under 5,000 m peaks, which traps its smog.' },
  { n: 'Valparaíso', c: 'Chile', lat: -33.0472, lon: -71.6127, d: 5, r: 'S America',
    q: 'A port of steep hills and funicular lifts that lost its business when a canal opened.',
    s: 'The Panama Canal in 1914 ended its role as the stop after Cape Horn. Chile’s congress meets here rather than in the capital.' },
  { n: 'San Pedro de Atacama', c: 'Chile', lat: -22.9087, lon: -68.1997, d: 5, r: 'S America',
    q: 'Some weather stations in this desert have never recorded rain.',
    s: 'It is the driest non-polar desert on Earth, which is why the big telescope arrays are here. NASA tests Mars rovers on the ground nearby.' },
  { n: 'Lima', c: 'Peru', lat: -12.0464, lon: -77.0428, d: 2, r: 'S America',
    q: 'A capital of ten million in a desert that gets about 10 mm of rain a year.',
    s: 'Water comes from Andean rivers, and coastal fog called garúa hangs over it for months. Pizarro founded it in 1535 as the City of Kings.' },
  { n: 'Machu Picchu', c: 'Peru', lat: -13.1631, lon: -72.5450, d: 2, r: 'S America',
    q: 'A ridge-top estate the Spanish never found, shown to an American by a local boy in 1911.',
    s: 'Hiram Bingham was actually looking for a different city. The stonework has no mortar and has ridden out five centuries of earthquakes.' },
  { n: 'Cusco', c: 'Peru', lat: -13.5319, lon: -71.9675, d: 3, r: 'S America',
    q: 'The Inca capital, laid out in the shape of a puma, with Spanish churches on its walls.',
    s: 'Inca foundations survived the 1650 and 1950 earthquakes that brought down colonial buildings above them. It sits at 3,400 m.' },
  { n: 'Nazca', c: 'Peru', lat: -14.7390, lon: -75.1300, d: 5, r: 'S America',
    q: 'Vast line drawings here were only recognised once people started flying over them.',
    s: 'They were made by clearing dark stones off pale ground, and survive because it almost never rains or blows hard. Some are 370 m across.' },
  { n: 'La Paz', c: 'Bolivia', lat: -16.4897, lon: -68.1193, d: 3, r: 'S America',
    q: 'The highest seat of government in the world, with a cable car network as public transit.',
    s: 'Mi Teleférico carries commuters up 3,600–4,100 m slopes. Constitutionally the capital is elsewhere, in Sucre.' },
  { n: 'Salar de Uyuni', c: 'Bolivia', lat: -20.1338, lon: -67.4891, d: 4, r: 'S America',
    q: 'The world’s largest salt flat becomes a perfect mirror when a thin film of water sits on it.',
    s: 'It is so flat — under a metre of variation over 10,000 km² — that satellites use it for calibration. It holds a large share of the world’s lithium.' },
  { n: 'Potosí', c: 'Bolivia', lat: -19.5836, lon: -65.7531, d: 5, r: 'S America',
    q: 'A mountain of silver here funded the Spanish empire and killed vast numbers of workers.',
    s: 'In 1600 this was one of the largest cities in the world at 4,000 m. The Spanish phrase "vale un potosí" still means worth a fortune.' },
  { n: 'Quito', c: 'Ecuador', lat: -0.1807, lon: -78.4678, d: 3, r: 'S America',
    q: 'A capital 25 km from the equator, sitting at 2,850 m on the flank of a volcano.',
    s: 'It was the first city given World Heritage status in 1978. A monument marks the equator nearby, though GPS later put the line 240 m away.' },
  { n: 'Galápagos Islands', c: 'Ecuador', lat: -0.7437, lon: -90.3139, d: 3, r: 'S America',
    q: 'A five-week visit here in 1835 gave a young naturalist a problem he chewed on for decades.',
    s: 'Darwin did not work out the finches until an ornithologist sorted his mislabelled specimens back in London. The islands sit on a hotspot 900 km offshore.' },
  { n: 'Bogotá', c: 'Colombia', lat: 4.7110, lon: -74.0721, d: 3, r: 'S America',
    q: 'A capital at 2,640 m that closes 120 km of streets to cars every Sunday.',
    s: 'The Ciclovía draws over a million people weekly and has been copied worldwide. Its gold museum holds 55,000 pieces.' },
  { n: 'Cartagena', c: 'Colombia', lat: 10.3910, lon: -75.4794, d: 4, r: 'S America',
    q: 'Eleven kilometres of walls were built around this port because it kept being sacked.',
    s: 'Francis Drake held it to ransom in 1586. A British assault of 25,000 men failed in 1741 against a one-eyed, one-legged, one-armed defender.' },
  { n: 'Caracas', c: 'Venezuela', lat: 10.4806, lon: -66.9036, d: 4, r: 'S America',
    q: 'A capital separated from its port by a mountain and a viaduct that collapsed in 2006.',
    s: 'Avila rises to 2,700 m directly behind the city. The country holds the largest proven oil reserves in the world.' },
  { n: 'Angel Falls', c: 'Venezuela', lat: 5.9701, lon: -62.5362, d: 5, r: 'S America',
    q: 'Water drops 979 m from a flat-topped mountain here, and much of it turns to mist first.',
    s: 'A US pilot crash-landed on the tabletop in 1937 looking for ore and walked out over 11 days. The flat mesas inspired The Lost World.' },
  { n: 'Asunción', c: 'Paraguay', lat: -25.2637, lon: -57.5759, d: 5, r: 'S America',
    q: 'A capital in a landlocked country that lost most of its adult men in a 19th-century war.',
    s: 'The War of the Triple Alliance killed a huge share of the population by 1870. Guaraní is spoken by most of the country alongside Spanish.' },
  { n: 'Montevideo', c: 'Uruguay', lat: -34.9011, lon: -56.1645, d: 4, r: 'S America',
    q: 'The first football World Cup was played in this capital in 1930, and the hosts won.',
    s: 'Some European teams refused the boat trip. A German pocket battleship was scuttled off the coast here in 1939.' },
  { n: 'Georgetown', c: 'Guyana', lat: 6.8013, lon: -58.1551, d: 5, r: 'S America',
    q: 'An English-speaking South American capital sitting below sea level behind a sea wall.',
    s: 'Dutch engineers built the drainage system with kokers, sluice gates still in use. Enormous offshore oil finds since 2015 are transforming the economy.' },
  { n: 'Paramaribo', c: 'Suriname', lat: 5.8520, lon: -55.2038, d: 5, r: 'S America',
    q: 'A Dutch-speaking capital that Britain traded away for New Amsterdam.',
    s: 'The 1667 Treaty of Breda swapped this colony for Manhattan. Its wooden colonial centre is a World Heritage site.' },
  { n: 'Easter Island', c: 'Chile', lat: -27.1127, lon: -109.3497, d: 4, r: 'S America',
    q: 'Nearly 900 carved figures stand on the most remote inhabited island on Earth.',
    s: 'The nearest inhabited land is 2,000 km away. Most moai face inland, watching over the villages rather than the sea.' },

  /* --------------------------------------------------------- North America */
  { n: 'New York City', c: 'United States of America', lat: 40.7128, lon: -74.0060, d: 1, r: 'N America',
    q: 'The Dutch bought this island in 1626 for goods worth about 60 guilders.',
    s: 'The famous $24 figure is a 19th-century conversion and roughly meaningless. The city was the US capital until 1790, and Washington was sworn in on Wall Street.' },
  { n: 'Washington, D.C.', c: 'United States of America', lat: 38.9072, lon: -77.0369, d: 1, r: 'N America',
    q: 'British troops burned this capital in 1814 and a storm put the fires out.',
    s: 'A hurricane and possible tornado struck the next day. The presidential mansion was painted white to cover the scorch marks, or so the story goes.' },
  { n: 'Boston', c: 'United States of America', lat: 42.3601, lon: -71.0589, d: 2, r: 'N America',
    q: 'Protesters dressed as Mohawks dumped 342 chests of tea in this harbour in 1773.',
    s: 'The cargo was worth about £10,000, roughly $1.7 million today. A molasses tank burst in the same city in 1919 and killed 21 people in a wave of syrup.' },
  { n: 'Philadelphia', c: 'United States of America', lat: 39.9526, lon: -75.1652, d: 2, r: 'N America',
    q: 'Two founding documents were signed in the same building here, eleven years apart.',
    s: 'Independence Hall hosted both the Declaration and the Constitution. The city was the US capital for a decade while Washington was being built.' },
  { n: 'Chicago', c: 'United States of America', lat: 41.8781, lon: -87.6298, d: 2, r: 'N America',
    q: 'Engineers reversed the direction of this city’s river in 1900.',
    s: 'It was carrying sewage into the drinking-water lake, so they made it flow inland instead. The first skyscraper with a steel frame went up here in 1885.' },
  { n: 'New Orleans', c: 'United States of America', lat: 29.9511, lon: -90.0715, d: 2, r: 'N America',
    q: 'The United States bought 2.1 million km² from France in 1803 for about 3 cents an acre.',
    s: 'This port was the point of the whole purchase — control of the river mouth. Most of the city sits below sea level behind levees.' },
  { n: 'Los Angeles', c: 'United States of America', lat: 34.0522, lon: -118.2437, d: 1, r: 'N America',
    q: 'Filmmakers moved here partly to be far from Edison’s patent enforcers back east.',
    s: 'The Mexican border was also close if lawyers showed up. A sign advertising a housing development in 1923 lost its last four letters and became the city’s emblem.' },
  { n: 'San Francisco', c: 'United States of America', lat: 37.7749, lon: -122.4194, d: 1, r: 'N America',
    q: 'An 1849 gold rush turned a village of 1,000 into a city of 25,000 in a year.',
    s: 'Ships were abandoned in the bay as crews ran for the hills; some are still buried under the financial district. A 1906 quake and fire destroyed 80% of the city.' },
  { n: 'Seattle', c: 'United States of America', lat: 47.6062, lon: -122.3321, d: 2, r: 'N America',
    q: 'This city hosted a 1962 world’s fair and kept the spaceship-shaped tower.',
    s: 'The Space Needle was designed on a napkin and built in under a year. The city gets less annual rainfall than New York, just spread over far more days.' },
  { n: 'Las Vegas', c: 'United States of America', lat: 36.1699, lon: -115.1398, d: 2, r: 'N America',
    q: 'A dam built 50 km away in the 1930s gave this desert town power and workers with wages.',
    s: 'Gambling was legalised in 1931 the same year the dam broke ground. Atmospheric nuclear tests to the north were once a tourist attraction here.' },
  { n: 'Miami', c: 'United States of America', lat: 25.7617, lon: -80.1918, d: 2, r: 'N America',
    q: 'A woman named Julia Tuttle persuaded a railway magnate to extend his line here in 1896.',
    s: 'She reportedly sent him orange blossoms to prove a freeze had spared the area. She remains the only woman to have founded a major US city.' },
  { n: 'Detroit', c: 'United States of America', lat: 42.3314, lon: -83.0458, d: 3, r: 'N America',
    q: 'A moving assembly line here in 1913 cut car build time from 12 hours to 93 minutes.',
    s: 'Ford then doubled wages to $5 a day to stop workers quitting from boredom. Oddly, the city lies north of part of Canada.' },
  { n: 'Anchorage', c: 'United States of America', lat: 61.2181, lon: -149.9003, d: 3, r: 'N America',
    q: 'The second-largest earthquake ever recorded struck near this city on Good Friday 1964.',
    s: 'It hit magnitude 9.2 and lasted four and a half minutes; some land dropped two metres. The US bought the territory in 1867 for about two cents an acre.' },
  { n: 'Honolulu', c: 'United States of America', lat: 21.3069, lon: -157.8583, d: 2, r: 'N America',
    q: 'Aircraft attacked the naval base beside this city just before 8 a.m. on 7 December 1941.',
    s: 'A radar operator saw the incoming flight and was told to forget it — bombers were expected from California. This is the most remote major city on Earth.' },
  { n: 'Cape Canaveral', c: 'United States of America', lat: 28.3922, lon: -80.6077, d: 3, r: 'N America',
    q: 'Rockets launch east from here because the site is close to the equator with ocean downrange.',
    s: 'The Earth’s spin gives a free 400 m/s eastward. Apollo 11 left from the pad next door in July 1969.' },
  { n: 'Gettysburg', c: 'United States of America', lat: 39.8309, lon: -77.2311, d: 4, r: 'N America',
    q: 'A three-day battle here in 1863 was followed months later by a two-minute speech.',
    s: 'The main speaker that day talked for two hours; nobody remembers a word. Lincoln’s 271 words were thought at the time to have fallen flat.' },
  { n: 'Kitty Hawk', c: 'United States of America', lat: 36.0646, lon: -75.7057, d: 5, r: 'N America',
    q: 'Two bicycle mechanics chose this windy coast for its steady breeze and soft sand.',
    s: 'The first flight in December 1903 covered 37 m in 12 seconds, shorter than a modern airliner. Only a handful of newspapers bothered to report it.' },
  { n: 'Los Alamos', c: 'United States of America', lat: 35.8800, lon: -106.3031, d: 5, r: 'N America',
    q: 'A boys’ school on a mesa was requisitioned in 1943 and everyone’s mail went to one PO box.',
    s: 'Children born there had "PO Box 1663" as their birthplace. The site was picked for isolation and because Oppenheimer knew the area from riding holidays.' },
  { n: 'Yellowstone', c: 'United States of America', lat: 44.4280, lon: -110.5885, d: 3, r: 'N America',
    q: 'The world’s first national park, sitting on top of a supervolcano caldera.',
    s: 'Established in 1872, before the state around it existed. Half the world’s geysers are here, driven by magma a few kilometres down.' },
  { n: 'Grand Canyon', c: 'United States of America', lat: 36.1069, lon: -112.1129, d: 2, r: 'N America',
    q: 'A river cut 1.6 km down through rock recording two billion years of history.',
    s: 'The oldest layers at the bottom are roughly half the age of the Earth. A US Army report in 1858 called the place "altogether valueless".' },
  { n: 'Mount Rushmore', c: 'United States of America', lat: 43.8791, lon: -103.4591, d: 4, r: 'N America',
    q: 'Four faces were blasted into a granite ridge with dynamite between 1927 and 1941.',
    s: 'Around 90% of the rock was removed by explosives handled precisely enough to leave the features. The sculptor planned torsos but funding ran out.' },
  { n: 'Memphis', c: 'United States of America', lat: 35.1495, lon: -90.0490, d: 4, r: 'N America',
    q: 'Martin Luther King was shot on a motel balcony in this city in April 1968.',
    s: 'He was there supporting a sanitation workers’ strike. The motel is now the National Civil Rights Museum, with the room preserved.' },
  { n: 'Selma', c: 'United States of America', lat: 32.4074, lon: -87.0211, d: 5, r: 'N America',
    q: 'Marchers were beaten on a bridge here on 7 March 1965, and television carried it live.',
    s: 'The footage interrupted a Sunday night film. The Voting Rights Act passed five months later.' },
  { n: 'Death Valley', c: 'United States of America', lat: 36.5323, lon: -116.9325, d: 4, r: 'N America',
    q: 'The highest reliably recorded air temperature on Earth, 56.7 °C, was measured here in 1913.',
    s: 'Badwater Basin is 86 m below sea level, and the highest peak in the contiguous states is 135 km away. Rocks on one playa move by themselves on thin winter ice.' },
  { n: 'Roswell', c: 'United States of America', lat: 33.3943, lon: -104.5230, d: 5, r: 'N America',
    q: 'An air base here announced it had recovered a "flying disc" in July 1947, then retracted it.',
    s: 'The debris came from Project Mogul, a classified balloon programme listening for Soviet bomb tests. The retraction is what made the story immortal.' },
  { n: 'Toronto', c: 'Canada', lat: 43.6532, lon: -79.3832, d: 2, r: 'N America',
    q: 'A concrete tower here was the world’s tallest free-standing structure for 32 years.',
    s: 'The CN Tower was built in 1976 to fix radio reception blocked by new skyscrapers. Over half the city’s residents were born outside Canada.' },
  { n: 'Montreal', c: 'Canada', lat: 45.5019, lon: -73.5674, d: 2, r: 'N America',
    q: 'The second-largest French-speaking city in the world, on an island in a river.',
    s: 'A 1976 Olympic stadium debt took 30 years to pay off. Its underground city runs 32 km, which matters at −25 °C.' },
  { n: 'Vancouver', c: 'Canada', lat: 49.2827, lon: -123.1207, d: 2, r: 'N America',
    q: 'A Pacific port where you can ski and sail on the same day.',
    s: 'It sits at the same latitude as Paris but is warmed by ocean currents. Stanley Park is bigger than Central Park and is mostly rainforest.' },
  { n: 'Ottawa', c: 'Canada', lat: 45.4215, lon: -75.6972, d: 3, r: 'N America',
    q: 'Queen Victoria picked this lumber town as a capital in 1857 as a compromise.',
    s: 'It was far enough from the US border to be defensible and sat between English and French Canada. Its canal freezes into the world’s largest skating rink.' },
  { n: 'Quebec City', c: 'Canada', lat: 46.8139, lon: -71.2080, d: 3, r: 'N America',
    q: 'A 1759 battle on a plateau above this walled city decided who would run Canada.',
    s: 'Both commanders died within days. It is the only walled city north of Mexico and was founded in 1608.' },
  { n: 'Churchill', c: 'Canada', lat: 58.7684, lon: -94.1650, d: 5, r: 'N America',
    q: 'A town where people leave their cars unlocked in case someone needs to escape a bear.',
    s: 'Polar bears gather here waiting for Hudson Bay to freeze. There is a holding facility for repeat offenders, informally the bear jail.' },
  { n: 'Iqaluit', c: 'Canada', lat: 63.7467, lon: -68.5170, d: 5, r: 'N America',
    q: 'The capital of a territory created in 1999, reachable only by air or a short summer sealift.',
    s: 'Nunavut covers a fifth of Canada and has about 40,000 people. No roads connect this town to anywhere else.' },
  { n: 'Dawson City', c: 'Canada', lat: 64.0601, lon: -139.4333, d: 5, r: 'N America',
    q: 'A gold strike in 1896 drew 100,000 people toward this river junction; 30,000 made it.',
    s: 'Most arrived after the good claims were gone. A bar in town still serves a cocktail containing a preserved human toe.' },
  { n: 'L’Anse aux Meadows', c: 'Canada', lat: 51.5964, lon: -55.5320, d: 5, r: 'N America',
    q: 'Norse turf houses found here in 1960 proved Europeans reached the Americas around 1000.',
    s: 'Tree-ring dating of the wood later pinned one year exactly: 1021. The settlement lasted only a few years.' },
  { n: 'Mexico City', c: 'Mexico', lat: 19.4326, lon: -99.1332, d: 1, r: 'N America',
    q: 'This capital was built on a drained lake and is sinking about 50 cm a year in places.',
    s: 'The Aztec island city of Tenochtitlan was here, and Spanish colonists drained the lake around it. The cathedral visibly tilts.' },
  { n: 'Teotihuacan', c: 'Mexico', lat: 19.6925, lon: -98.8438, d: 4, r: 'N America',
    q: 'The Aztecs found this city already abandoned and named it "birthplace of the gods".',
    s: 'At its height around AD 450 it held 125,000 people. Nobody knows what its builders called themselves or what language they spoke.' },
  { n: 'Chichén Itzá', c: 'Mexico', lat: 20.6843, lon: -88.5678, d: 3, r: 'N America',
    q: 'A stepped pyramid here throws a serpent-shaped shadow twice a year.',
    s: 'The equinox effect is precise enough to draw crowds. Clapping in front of the staircase returns a chirp resembling the quetzal bird.' },
  { n: 'Oaxaca', c: 'Mexico', lat: 17.0732, lon: -96.7266, d: 5, r: 'N America',
    q: 'A valley city where mole sauce, mezcal and a famous Day of the Dead all come together.',
    s: 'Sixteen indigenous groups live in the state. The hilltop ruin of Monte Albán above the city was levelled by hand around 500 BC.' },
  { n: 'Havana', c: 'Cuba', lat: 23.1136, lon: -82.3666, d: 2, r: 'N America',
    q: 'An American battleship blew up in this harbour in 1898 and started a war.',
    s: 'The USS Maine’s loss was probably an internal coal-bunker fire, not sabotage. Spain lost its last American colonies within months.' },
  { n: 'Guantánamo Bay', c: 'Cuba', lat: 19.9061, lon: -75.2094, d: 5, r: 'N America',
    q: 'The US pays rent on this base under a 1903 lease and Cuba refuses to cash the cheques.',
    s: 'The amount is about $4,085 a year. It is the oldest overseas US naval base and the lease has no end date.' },
  { n: 'Kingston', c: 'Jamaica', lat: 17.9714, lon: -76.7931, d: 4, r: 'N America',
    q: 'A 1692 earthquake dropped this harbour’s pirate town straight into the sea.',
    s: 'Port Royal, called the wickedest city on Earth, lost two-thirds of its buildings in minutes. The modern capital grew from the refugees.' },
  { n: 'Port-au-Prince', c: 'Haiti', lat: 18.5944, lon: -72.3074, d: 4, r: 'N America',
    q: 'The capital of the first country founded by a successful slave revolt.',
    s: 'Independence came in 1804, then France demanded reparations for lost "property" — a debt not cleared until 1947. A 2010 earthquake killed over 200,000.' },
  { n: 'Panama City', c: 'Panama', lat: 8.9824, lon: -79.5199, d: 3, r: 'N America',
    q: 'Ships sail from the Pacific to the Atlantic here by heading north-west.',
    s: 'The isthmus twists, so the canal’s Pacific end is east of its Caribbean end. About 25,000 workers died building it, most from disease.' },
  { n: 'Tikal', c: 'Guatemala', lat: 17.2220, lon: -89.6237, d: 5, r: 'N America',
    q: 'Temples rising above the jungle canopy here stood in for a rebel base in a 1977 film.',
    s: 'The Maya city held perhaps 90,000 people and collapsed in the 9th century. Its reservoirs were engineered to get through months without rain.' },
  { n: 'San Salvador', c: 'El Salvador', lat: 13.6929, lon: -89.2182, d: 5, r: 'N America',
    q: 'The capital of the smallest country on the American mainland, which made bitcoin legal tender in 2021.',
    s: 'The country is the most densely populated on the mainland and sits on a volcanic chain, which is why it keeps rebuilding this city.' },
  { n: 'Nuuk', c: 'Greenland', lat: 64.1836, lon: -51.7214, d: 4, r: 'N America',
    q: 'The capital of the world’s largest island, with about 19,000 people.',
    s: 'The island is 80% ice sheet, up to 3 km thick. Its map projection makes it look the size of Africa; Africa is 14 times larger.' },

  /* --------------------------------------------------------------- Oceania */
  { n: 'Sydney', c: 'Australia', lat: -33.8688, lon: 151.2093, d: 1, r: 'Oceania',
    q: 'An opera house here came in ten years late and fourteen times over budget.',
    s: 'Utzon quit in 1966 and never saw it finished. It was paid for by a state lottery, and the shells are sections of one sphere.' },
  { n: 'Melbourne', c: 'Australia', lat: -37.8136, lon: 144.9631, d: 2, r: 'Oceania',
    q: 'This was Australia’s capital for 26 years while a new one was being built.',
    s: 'It served from 1901 to 1927 as the compromise between the two rivals. It was briefly the richest city in the world during the 1850s gold rush.' },
  { n: 'Canberra', c: 'Australia', lat: -35.2809, lon: 149.1300, d: 3, r: 'Oceania',
    q: 'A capital designed by competition winners from Chicago, placed between two feuding cities.',
    s: 'Walter and Marion Griffin won in 1912 with drawings Marion rendered. The site is roughly halfway between Sydney and Melbourne, which was the entire point.' },
  { n: 'Perth', c: 'Australia', lat: -31.9505, lon: 115.8605, d: 3, r: 'Oceania',
    q: 'One of the most isolated cities on Earth; the nearest million-person city is 2,100 km away.',
    s: 'Residents turned on their lights in 1962 as John Glenn passed overhead, earning it the nickname City of Light.' },
  { n: 'Darwin', c: 'Australia', lat: -12.4634, lon: 130.8456, d: 4, r: 'Oceania',
    q: 'Japanese aircraft bombed this town in February 1942 with more bombs than fell on Pearl Harbor.',
    s: 'There were 64 raids in all. A cyclone then destroyed 70% of the town on Christmas Eve 1974.' },
  { n: 'Uluru', c: 'Australia', lat: -25.3444, lon: 131.0369, d: 3, r: 'Oceania',
    q: 'A sandstone monolith that continues underground for perhaps several kilometres.',
    s: 'What you see is the tip of a tilted rock slab. Climbing it was banned in 2019 at the request of the Anangu traditional owners.' },
  { n: 'Hobart', c: 'Australia', lat: -42.8821, lon: 147.3272, d: 4, r: 'Oceania',
    q: 'A southern island capital that is the usual last port before Antarctic expeditions.',
    s: 'It is Australia’s second-oldest city, founded as a penal settlement in 1804. A private museum built into a cliff here is largely underground.' },
  { n: 'Coober Pedy', c: 'Australia', lat: -29.0139, lon: 134.7533, d: 5, r: 'Oceania',
    q: 'Most people in this opal-mining town live underground to escape 50 °C heat.',
    s: 'Homes, churches and hotels are all dug into the rock, staying about 23 °C year-round. The name comes from words meaning "white man in a hole".' },
  { n: 'Auckland', c: 'New Zealand', lat: -36.8485, lon: 174.7633, d: 2, r: 'Oceania',
    q: 'A city of 1.7 million built on about 50 separate volcanoes.',
    s: 'The field is dormant but not extinct; the youngest cone erupted around 600 years ago. It has more boats per head than almost anywhere.' },
  { n: 'Wellington', c: 'New Zealand', lat: -41.2866, lon: 174.7756, d: 3, r: 'Oceania',
    q: 'The southernmost capital city in the world, and one of the windiest.',
    s: 'Gales over 60 km/h blow about 175 days a year through the Cook Strait funnel. The parliament’s executive wing is known as the Beehive.' },
  { n: 'Christchurch', c: 'New Zealand', lat: -43.5321, lon: 172.6362, d: 4, r: 'Oceania',
    q: 'A 2011 earthquake here was small in magnitude but among the most destructive ever recorded.',
    s: 'It was shallow, close and directly under the city, producing extreme ground acceleration. The cathedral lost its spire and the centre was cordoned for years.' },
  { n: 'Rotorua', c: 'New Zealand', lat: -38.1368, lon: 176.2497, d: 5, r: 'Oceania',
    q: 'A town that smells permanently of sulphur, with geysers and boiling mud in the parks.',
    s: 'It sits on a caldera in the Taupō volcanic zone. Māori here cook food in steam vents, and have for centuries.' },
  { n: 'Waitangi', c: 'New Zealand', lat: -35.2667, lon: 174.0833, d: 5, r: 'Oceania',
    q: 'A treaty signed on this lawn in 1840 exists in two versions that do not agree.',
    s: 'The English text cedes sovereignty; the Māori text cedes governance while keeping chieftainship. The gap has driven legal claims ever since.' },
  { n: 'Port Moresby', c: 'Papua New Guinea', lat: -9.4438, lon: 147.1803, d: 4, r: 'Oceania',
    q: 'The capital of a country where over 800 languages are spoken.',
    s: 'That is roughly 12% of all human languages among 10 million people, a result of mountains separating valleys for millennia.' },
  { n: 'Suva', c: 'Fiji', lat: -18.1416, lon: 178.4419, d: 4, r: 'Oceania',
    q: 'A capital on an island group the date line was bent around.',
    s: 'The line jogs east so the whole country shares one day. Rugby sevens is close to a national religion here.' },
  { n: 'Nouméa', c: 'New Caledonia', lat: -22.2758, lon: 166.4580, d: 5, r: 'Oceania',
    q: 'A French-speaking Pacific capital holding roughly a quarter of the world’s nickel.',
    s: 'It sits inside the world’s second-largest barrier reef. France used the territory as a penal colony in the 1800s.' },
  { n: 'Port Vila', c: 'Vanuatu', lat: -17.7333, lon: 168.3273, d: 5, r: 'Oceania',
    q: 'The capital of a country ruled jointly by Britain and France, with two of every institution.',
    s: 'The condominium had duplicate police forces, courts and currencies until independence in 1980. Land divers on one island inspired bungee jumping.' },
  { n: 'Apia', c: 'Samoa', lat: -13.8333, lon: -171.7667, d: 5, r: 'Oceania',
    q: 'This country skipped 30 December 2011 entirely to switch sides of the date line.',
    s: 'It moved to trade more easily with Australia and New Zealand. Robert Louis Stevenson spent his last years here and is buried above the town.' },
  { n: 'Papeete', c: 'Fr. Polynesia', lat: -17.5516, lon: -149.5585, d: 5, r: 'Oceania',
    q: 'Gauguin arrived at this port in 1891 looking for a place untouched by Europe.',
    s: 'He found a French colonial town and moved on. The islands cover an ocean area the size of Europe with about 4,000 km² of land.' },
  { n: 'Guam', c: 'Guam', lat: 13.4745, lon: 144.7504, d: 5, r: 'Oceania',
    q: 'A Japanese soldier hid in this island’s jungle until 1972, still at war.',
    s: 'Shoichi Yokoi survived 28 years on frogs, snails and hand-woven clothing. The island is a US territory whose residents cannot vote for president.' },

  /* ------------------------------------------------------------------ Polar */
  { n: 'McMurdo Station', c: 'Antarctica', lat: -77.8419, lon: 166.6863, d: 4, r: 'Polar',
    q: 'The largest settlement on its continent, with a bar, a chapel and about 1,000 summer residents.',
    s: 'It sits on volcanic rock at the far south of a sea, and is the logistics hub for most US Antarctic science. Winter population drops to around 150.' },
  { n: 'Amundsen–Scott Station', c: 'Antarctica', lat: -90.0000, lon: 0.0000, d: 3, r: 'Polar',
    q: 'A base where every direction is north and the sun rises and sets once a year.',
    s: 'It sits on ice 2,700 m thick that flows about 10 m a year, so the marker is repositioned each January.' },
  { n: 'Vostok Station', c: 'Antarctica', lat: -78.4645, lon: 106.8340, d: 5, r: 'Polar', x: 1,
    q: 'The lowest natural temperature ever recorded, −89.2 °C, was measured at this base in 1983.',
    s: 'Beneath it lies a liquid lake sealed under 4 km of ice for millions of years. Ice cores drilled here gave 420,000 years of climate record.' },
  { n: 'North Pole', c: null, lat: 90.0000, lon: 0.0000, d: 2, r: 'Polar',
    q: 'There is no land here at all — just drifting sea ice over 4,000 m of water.',
    s: 'Any flag planted here moves with the floe. A Russian submersible placed a titanium flag on the seabed below in 2007.' },

  /* ------------------------------------------------- the rest of the world */
  { n: 'Nuremberg', c: 'Germany', lat: 49.4521, lon: 11.0767, d: 3, r: 'Europe',
    q: 'Twenty-two men were tried in this city’s Palace of Justice from November 1945.',
    s: 'It was chosen because the courthouse and its attached prison had survived the bombing, and because the Nazi party had held its rallies here.' },
  { n: 'Dresden', c: 'Germany', lat: 51.0504, lon: 13.7373, d: 3, r: 'Europe',
    q: 'A firestorm destroyed this baroque city over two nights in February 1945.',
    s: 'Its Frauenkirche was left as rubble for 45 years, then rebuilt using 3,800 original stones, dark against the new pale ones.' },
  { n: 'Dunkirk', c: 'France', lat: 51.0343, lon: 2.3768, d: 4, r: 'Europe',
    q: 'Around 338,000 men were lifted off these beaches in nine days in 1940.',
    s: 'Hundreds of civilian boats crossed to help. Churchill called it a deliverance, not a victory, and warned that wars are not won by evacuations.' },
  { n: 'Santiago de Compostela', c: 'Spain', lat: 42.8805, lon: -8.5457, d: 4, r: 'Europe',
    q: 'Pilgrims have walked 800 km across northern Spain to this cathedral for a thousand years.',
    s: 'A giant censer swings across the transept, originally to mask the smell of the pilgrims. Over 300,000 people complete the walk each year.' },
  { n: 'Valletta', c: 'Malta', lat: 35.8989, lon: 14.5146, d: 4, r: 'Europe',
    q: 'Knights built this fortress capital after surviving a siege in 1565.',
    s: 'The island was the most bombed place on Earth in 1942, taking 6,700 tonnes in one month. The whole city is a World Heritage site of 0.8 km².' },
  { n: 'Pisa', c: 'Italy', lat: 43.7228, lon: 10.4017, d: 3, r: 'Europe',
    q: 'A bell tower here began leaning before the third storey was finished in 1178.',
    s: 'Soft ground on one side did it. Engineers removed soil from the high side in the 1990s and pulled it back to a safe 4°, where it should hold for 200 years.' },
  { n: 'Rovaniemi', c: 'Finland', lat: 66.5039, lon: 25.7294, d: 5, r: 'Europe',
    q: 'A town rebuilt after 1944 on a street plan shaped like a reindeer’s head.',
    s: 'Alvar Aalto drew it. It sits right on the Arctic Circle and has claimed Santa Claus as a resident since the 1950s.' },
  { n: 'Zermatt', c: 'Switzerland', lat: 45.9763, lon: 7.6586, d: 4, r: 'Europe',
    q: 'A car-free village under a pyramid peak that killed four of the seven men who first climbed it.',
    s: 'The 1865 descent from the Matterhorn ended when a rope snapped. The mountain’s shape comes from glaciers eroding four faces at once.' },
  { n: 'Osaka', c: 'Japan', lat: 34.6937, lon: 135.5023, d: 3, r: 'Asia',
    q: 'A merchant city whose people stand on the opposite side of the escalator to the capital’s.',
    s: 'It was the country’s kitchen and rice market, and gave the world the first futures exchange in the 1730s.' },
  { n: 'Fukushima Daiichi', c: 'Japan', lat: 37.4211, lon: 141.0328, d: 5, r: 'Asia',
    q: 'A 15-metre wave overtopped this plant’s seawall in March 2011 and drowned its generators.',
    s: 'The reactors survived the quake and shut down correctly; losing cooling power caused the meltdowns. The seawall had been designed for 5.7 m.' },
  { n: 'Nanjing', c: 'China', lat: 32.0603, lon: 118.7969, d: 4, r: 'Asia',
    q: 'A former southern capital whose name simply means "southern capital".',
    s: 'It served as the seat of the Republic of China. Its 14th-century city wall is the longest ever built around a city, over 35 km.' },
  { n: 'Chongqing', c: 'China', lat: 29.5630, lon: 106.5516, d: 5, r: 'Asia',
    q: 'A mountain city of stairs and fog that was China’s wartime capital from 1938.',
    s: 'Fog and hills made it hard to bomb accurately, though it was bombed for years. Its administrative area holds over 30 million people.' },
  { n: 'Macau', c: 'Macao', lat: 22.1987, lon: 113.5439, d: 4, r: 'Asia', x: 1,
    q: 'A Portuguese colony until 1999, now taking several times the gambling revenue of Las Vegas.',
    s: 'It is among the most densely populated places on Earth. Egg tarts here descend from Lisbon’s pastéis de nata by way of a British pharmacist.' },
  { n: 'Huế', c: 'Vietnam', lat: 16.4637, lon: 107.5909, d: 5, r: 'Asia',
    q: 'A month-long house-to-house battle in this imperial city in 1968 shifted American opinion on the war.',
    s: 'It was the Nguyen dynasty’s capital, with a citadel modelled on Beijing’s. Much of the complex was destroyed in the fighting.' },
  { n: 'Luang Prabang', c: 'Laos', lat: 19.8845, lon: 102.1348, d: 5, r: 'Asia',
    q: 'Monks in orange collect alms along this town’s streets at dawn, as they have for centuries.',
    s: 'It sits where the Nam Khan joins the Mekong, ringed by mountains. This country is the most heavily bombed per head in history, from the 1960s–70s.' },
  { n: 'Chiang Mai', c: 'Thailand', lat: 18.7883, lon: 98.9853, d: 4, r: 'Asia',
    q: 'A northern walled city founded in 1296 as the capital of a separate kingdom.',
    s: 'Lan Na was independent for centuries. Thousands of paper lanterns are released here each November at Yi Peng.' },
  { n: 'Kandy', c: 'Sri Lanka', lat: 7.2906, lon: 80.6337, d: 5, r: 'Asia',
    q: 'A temple in this hill town holds a tooth said to have been smuggled in a princess’s hair.',
    s: 'Possession of the relic was traditionally tied to the right to rule. The kingdom here held out against Europeans until 1815.' },
  { n: 'Jaipur', c: 'India', lat: 26.9124, lon: 75.7873, d: 4, r: 'Asia',
    q: 'A city painted pink in 1876 to welcome a visiting prince, and still repainted by law.',
    s: 'It was India’s first planned city, laid out on a grid in 1727. Its observatory holds the world’s largest stone sundial, accurate to two seconds.' },
  { n: 'Panaji', c: 'India', lat: 15.4909, lon: 73.8278, d: 5, r: 'Asia',
    q: 'India took this Portuguese territory by force in 1961, 14 years after independence.',
    s: 'Portugal had held it for 451 years and did not recognise the loss until 1974. Its churches and Konkani-Portuguese food make it unlike anywhere else in India.' },
  { n: 'Astana', c: 'Kazakhstan', lat: 51.1605, lon: 71.4704, d: 5, r: 'Asia',
    q: 'A capital built on frozen steppe from 1997, with a tent-shaped mall by Norman Foster.',
    s: 'It has changed name four times in thirty years. Winter lows reach −40 °C, making it the second-coldest capital after Ulaanbaatar.' },
  { n: 'Ashgabat', c: 'Turkmenistan', lat: 37.9601, lon: 58.3261, d: 5, r: 'Asia',
    q: 'A capital holding the record for the most white marble buildings in one place.',
    s: 'Over 500 of them, by official count. A gas crater 260 km north has been burning since Soviet engineers lit it decades ago.' },
  { n: 'Thimphu', c: 'Bhutan', lat: 27.4728, lon: 89.6390, d: 5, r: 'Asia',
    q: 'The only capital city in the world with no traffic lights.',
    s: 'One set was installed and removed after complaints. The country measures Gross National Happiness and did not allow television until 1999.' },
  { n: 'Malé', c: 'Maldives', lat: 4.1755, lon: 73.5093, d: 5, r: 'Asia',
    q: 'One of the most densely populated islands on Earth, in a country averaging 1.5 m above sea level.',
    s: 'The government held a cabinet meeting underwater in 2009 to make the point about rising seas, and has bought land abroad as insurance.' },
  { n: 'Bandar Seri Begawan', c: 'Brunei', lat: 4.9031, lon: 114.9398, d: 5, r: 'Asia',
    q: 'The capital of an oil-rich sultanate wrapped on three sides by Malaysia.',
    s: 'A water village of stilt houses beside it has been inhabited for over 1,300 years and has its own schools, mosques and fire station.' },
  { n: 'Kampala', c: 'Uganda', lat: 0.3476, lon: 32.5825, d: 4, r: 'Africa',
    q: 'Israeli commandos flew 4,000 km to rescue hostages at this city’s airport in 1976.',
    s: 'The Entebbe raid took about 90 minutes on the ground. The city is built across hills beside Africa’s largest lake.' },
  { n: 'Lusaka', c: 'Zambia', lat: -15.3875, lon: 28.3228, d: 5, r: 'Africa',
    q: 'A capital in a copper country that once ran a space programme out of a farmhouse.',
    s: 'Edward Nkoloso trained "Afronauts" in oil drums in 1964, funding never arrived, and the story has since become an art-world fixture.' },
  { n: 'Gaborone', c: 'Botswana', lat: -24.6282, lon: 25.9231, d: 5, r: 'Africa',
    q: 'A capital built from scratch in three years after diamonds were found post-independence.',
    s: 'The country went from one of the world’s poorest to middle income without a coup, and holds elections on schedule every five years.' },
  { n: 'Djibouti City', c: 'Djibouti', lat: 11.5721, lon: 43.1456, d: 5, r: 'Africa',
    q: 'A small country hosting military bases from the US, France, Japan, Italy and China at once.',
    s: 'It sits at the mouth of the Red Sea, where a huge share of world shipping passes. A salt lake nearby is the lowest point in Africa at −155 m.' },
  { n: 'Durban', c: 'South Africa', lat: -29.8587, lon: 31.0218, d: 5, r: 'Africa',
    q: 'A young lawyer was thrown off a train in this country in 1893 and stayed 21 years.',
    s: 'Gandhi developed satyagraha here before returning to India. The city has the largest Indian-descended population outside India.' },
  { n: 'Yaoundé', c: 'Cameroon', lat: 3.8480, lon: 11.5021, d: 5, r: 'Africa',
    q: 'The capital of a country with both French and English as official languages, on seven hills.',
    s: 'It was split between Britain and France after Germany lost the colony in 1916. Mount Cameroon on the coast is one of Africa’s most active volcanoes.' },
  { n: 'Niamey', c: 'Niger', lat: 13.5116, lon: 2.1254, d: 5, r: 'Africa',
    q: 'A capital on a great river in a country that is 80% desert.',
    s: 'The river arcs north into the Sahara before turning back south — an old course from when the region was wet. The country has the world’s highest birth rate.' },
  { n: 'Port Louis', c: 'Mauritius', lat: -20.1609, lon: 57.5012, d: 5, r: 'Africa',
    q: 'The last confirmed sighting of a certain flightless bird was on this island in 1662.',
    s: 'The dodo lasted under a century after Dutch sailors arrived. The island had no native land mammals and its birds had no fear of people.' },
  { n: 'Denver', c: 'United States of America', lat: 39.7392, lon: -104.9903, d: 3, r: 'N America',
    q: 'A city exactly one mile above sea level, where a step on the capitol marks the line.',
    s: 'Baseballs fly about 9% farther in the thin air, so the stadium stores them in a humidor. The airport’s public art has spawned a small industry of conspiracy theories.' },
  { n: 'Santa Fe', c: 'United States of America', lat: 35.6870, lon: -105.9378, d: 5, r: 'N America',
    q: 'The oldest state capital in the US, founded by Spain a decade before the Mayflower.',
    s: 'A 1610 settlement, and building codes still require adobe style downtown. At 2,194 m it is also the highest state capital.' },
  { n: 'Wounded Knee', c: 'United States of America', lat: 43.1428, lon: -102.3652, d: 5, r: 'N America',
    q: 'A disarmament that went wrong here in December 1890 killed around 250 Lakota.',
    s: 'It is usually taken as the end of the Indian Wars. Activists occupied the same site for 71 days in 1973.' },
  { n: 'Utqiaġvik', c: 'United States of America', lat: 71.2906, lon: -156.7886, d: 5, r: 'N America',
    q: 'The northernmost town in the US, where the sun does not rise for 65 days.',
    s: 'It also does not set for 80 days in summer. Known as Barrow until residents voted to restore the Iñupiaq name in 2016.' },
  { n: 'Halifax', c: 'Canada', lat: 44.6488, lon: -63.5752, d: 4, r: 'N America',
    q: 'Two ships collided in this harbour in 1917, one loaded with munitions.',
    s: 'The blast was the largest man-made explosion before nuclear weapons, killing about 2,000. Boston sent aid so fast that the city still sends Boston a Christmas tree every year.' },
  { n: 'Winnipeg', c: 'Canada', lat: 49.8951, lon: -97.1384, d: 5, r: 'N America',
    q: 'A bear cub bought at a station here in 1914 was named after the town and ended up in London Zoo.',
    s: 'A.A. Milne’s son met her there, and Winnie-the-Pooh followed. The city sits at a river junction that has been a trading site for 6,000 years.' },
  { n: 'Nassau', c: 'Bahamas', lat: 25.0443, lon: -77.3504, d: 4, r: 'N America',
    q: 'Pirates ran their own republic out of this harbour from 1706 until 1718.',
    s: 'Blackbeard and Hornigold operated from here until a governor arrived with pardons and a fleet. The islands are made of limestone with no rivers at all.' },
  { n: 'San Juan', c: 'Puerto Rico', lat: 18.4655, lon: -66.1057, d: 4, r: 'N America',
    q: 'Residents of this capital are US citizens who cannot vote for president while living there.',
    s: 'The territory has been US since 1898. Its old fortifications took 250 years to build and never fell to an attack from the sea.' },
  { n: 'Belize City', c: 'Belize', lat: 17.4995, lon: -88.1976, d: 5, r: 'N America',
    q: 'A hurricane in 1961 convinced this country to move its capital 80 km inland.',
    s: 'Belmopan was built on higher ground, though this remains the largest city. It is the only Central American country with English as the official language.' },
  { n: 'Hamilton', c: 'Bermuda', lat: 32.2949, lon: -64.7814, d: 5, r: 'N America',
    q: 'An island 1,000 km off the US coast whose name is attached to a triangle.',
    s: 'It has no rivers or lakes, so houses catch rainwater on stepped white roofs. It is the northernmost coral reef system in the world.' },
  { n: 'Medellín', c: 'Colombia', lat: 6.2442, lon: -75.5812, d: 4, r: 'S America',
    q: 'Cable cars and escalators up the hillsides here helped turn around the world’s most violent city.',
    s: 'The Metrocable connected barrios cut off by terrain. Its altitude gives it constant spring weather.' },
  { n: 'Iguazú Falls', c: 'Argentina', lat: -25.6953, lon: -54.4367, d: 4, r: 'S America',
    q: '275 separate cascades on a border, where Eleanor Roosevelt reportedly said "poor Niagara".',
    s: 'The main throat drops 82 m in a horseshoe you can stand inside the spray of. Three countries meet a few kilometres downstream.' },
  { n: 'Torres del Paine', c: 'Chile', lat: -50.9423, lon: -72.9863, d: 5, r: 'S America',
    q: 'Three granite towers in Patagonia, in a park where the wind regularly knocks people over.',
    s: 'Gusts pass 130 km/h. The towers are the eroded core of a magma intrusion that never reached the surface.' },
  { n: 'Recife', c: 'Brazil', lat: -8.0476, lon: -34.8770, d: 5, r: 'S America',
    q: 'The Dutch held this sugar port for 24 years and left behind the Americas’ first synagogue.',
    s: 'When Portugal retook it in 1654, some of the Jewish community sailed to New Amsterdam and founded the first Jewish community in what became New York.' },
  { n: 'Chan Chan', c: 'Peru', lat: -8.1060, lon: -79.0748, d: 5, r: 'S America',
    q: 'The largest mud-brick city ever built, on a coast where rain would dissolve it.',
    s: 'Twenty square kilometres of adobe survived because it almost never rains — except during El Niño, which is now the main threat to it.' },
  { n: 'Brisbane', c: 'Australia', lat: -27.4698, lon: 153.0251, d: 3, r: 'Oceania',
    q: 'A subtropical river city that was a penal settlement for repeat offenders.',
    s: 'It was deliberately placed far from Sydney for prisoners who reoffended. Around a million US troops passed through during the Pacific war.' },
  { n: 'Adelaide', c: 'Australia', lat: -34.9285, lon: 138.6007, d: 4, r: 'Oceania',
    q: 'The only Australian capital founded entirely by free settlers, with no convict history.',
    s: 'It was planned in 1837 on a grid ringed by parkland. Its colony gave women the vote in 1894, among the first anywhere.' },
  { n: 'Alice Springs', c: 'Australia', lat: -23.6980, lon: 133.8807, d: 4, r: 'Oceania',
    q: 'A town near the geographic centre of its country, founded as a telegraph repeater station.',
    s: 'The 1872 Overland Telegraph cut news time from London from months to hours. The School of the Air teaches children over radio across an area the size of France.' },
  { n: 'Queenstown', c: 'New Zealand', lat: -45.0312, lon: 168.6626, d: 5, r: 'Oceania',
    q: 'Commercial bungee jumping started off a bridge near this lake town in 1988.',
    s: 'A.J. Hackett and Henry van Asch took the idea from Vanuatu land divers. The lake sits in a glacier-carved trench 380 m deep.' },
  { n: 'Honiara', c: 'Solomon Is.', lat: -9.4456, lon: 159.9729, d: 5, r: 'Oceania',
    q: 'A six-month campaign for the airfield beside this capital ran from August 1942.',
    s: 'Guadalcanal was the first Allied land offensive against Japan. The strait offshore is called Ironbottom Sound for the ships sunk in it.' },
  { n: 'Funafuti', c: 'Tuvalu', lat: -8.5211, lon: 179.1962, d: 5, r: 'Oceania', x: 1,
    q: 'A country of 26 km² whose internet domain earns it a large share of national revenue.',
    s: 'Leasing .tv brings in millions a year. Its highest point is 4.6 m, and it is recording itself digitally to survive as a state if the land goes.' },
  { n: 'Nauru', c: 'Nauru', lat: -0.5228, lon: 166.9315, d: 5, r: 'Oceania',
    q: 'Phosphate from bird droppings briefly gave this island one of the world’s highest incomes.',
    s: 'Strip mining left 80% of it uninhabitable and the money was largely lost in bad investments. It is the smallest republic on Earth, at 21 km².' },
  { n: 'Grytviken', c: 'S. Geo. and the Is.', lat: -54.2811, lon: -36.5092, d: 5, r: 'Polar',
    q: 'Shackleton walked into this whaling station in 1916 after crossing 1,300 km of ocean in a lifeboat.',
    s: 'His entire crew survived nearly two years on the ice. He is buried here, and his men later drank a toast to "the Boss" over the grave.' },
  { n: 'Deception Island', c: 'Antarctica', lat: -62.9667, lon: -60.6333, d: 5, r: 'Polar',
    q: 'Ships sail through a narrow gap into the flooded crater of an active volcano here.',
    s: 'Neptune’s Bellows opens into a natural harbour that erupted in 1967 and 1969, wrecking two bases. Geothermal heat warms the shallows enough to swim.' },

  // eof-marker-do-not-remove
];

if (typeof module !== 'undefined' && module.exports) module.exports = LOCATIONS;
